window.EXPL={"변리사2018_55-03-2":{"f":"관습법은 사회의 거듭된 관행과 법적 확신이 있어야 성립된다.","w":"관습법은 사회의 거듭된 관행이 있고 그것이 법적 확신으로 뒷받침될 때 성립한다. 법적 확신이 없는 단순한 관행은 사실인 관습일 뿐이다.","c":"상"},"변리사2018_55-03-3":{"f":"관습법은 당사자의 주장입증을 기다림이 없이 법원이 직권으로 이를 확정하여야 한다.","w":"관습법은 법원이 직권으로 확정하지만, 사실인 관습은 그 존재를 당사자가 주장·입증해야 한다.","c":"중"},"변리사2018_55-03-4":{"f":"공동선조와 성과 본을 같이하는 후손이면 성별의 구별 없이 성년이 되면 당연히 종중의 구성원이 된다.","w":"종중원은 공동선조의 후손 중 성년이 된 사람이며, 미성년자는 종중원이 아니다. 성별은 따지지 않는다(대법원 2005.7.21. 전원합의체 판결).","c":"상"},"변리사2018_55-03-5":{"f":"관습법이 사회생활규범으로 승인되었더라도 사회를 지배하는 기본적 이념이나 사회질서의 변화로 인하여 그 관습법을 적용하여야 할 시점에 있어서의 전체 법질서에 부합하지 않게 되었다면 그 법규범으로서의 효력이 부정된다.","w":"관습법도 현재의 전체 법질서에 부합하지 않게 되면 효력이 부정된다(대법원 2005.7.21. 전원합의체 판결).","c":"상"},"변리사2018_55-04-1":{"f":"미성년자도 임의대리인이 될 수 있다.","w":"대리인은 행위능력자임을 요하지 않으므로 미성년자도 임의대리인이 될 수 있다(민법 제117조).","c":"상"},"변리사2018_55-04-3":{"f":"미성년자가 법정대리인의 동의 없이 법률행위를 한 경우에 법정대리인의 취소권이 기간경과로 소멸되지 않는 한, 미성년자는 성년이 된 후에도 취소할 수 있다.","w":"미성년자 본인도 취소할 수 있고, 성년이 된 뒤에도 취소권이 소멸하기 전이면 취소할 수 있다(민법 제5조, 제140조, 제146조).","c":"상"},"변리사2018_55-04-4":{"f":"甲이 乙과 계약을 체결할 당시 乙이 미성년자임을 알고 계약했다면 甲은 철회권을 행사할 수 없다.","w":"상대방의 철회권은 계약 당시 미성년자임을 알지 못한 선의의 상대방에게만 있다(민법 제16조 제1항).","c":"상"},"변리사2018_55-04-5":{"f":"미성년자가 법정대리인의 동의 없이 법률행위를 하면서 특약에 의하여 미성년을 이유로 한 취소를 하지 않기로 한 경우에도 미성년을 이유로 그 법률행위를 취소할 수 있다.","w":"제한능력자의 취소권을 미리 배제하는 특약은 제한능력자 보호 취지에 반하여 효력이 없다.","c":"중"},"변리사2018_55-07-2":{"f":"권리능력 없는 사단의 사원이 집합체로서 물건을 소유한 경우에는 총유로 한다.","w":"법인 아닌 사단의 사원이 집합체로서 물건을 소유하는 형태는 총유이다(민법 제275조). 합유는 조합의 소유 형태이다.","c":"상"},"변리사2018_55-07-3":{"f":"권리능력 없는 사단에 구성원이 없게 되더라도 그 사단은 바로 소멸하지 않고 소송상의 당사자능력도 바로 상실하지 않는다.","w":"구성원이 없게 되면 해산사유가 될 뿐이고, 청산이 끝날 때까지는 사단이 존속하여 당사자능력이 유지된다.","c":"중"},"변리사2018_55-07-4":{"f":"권리능력 없는 사단의 대표자는 정관에 규정이 없는 한 자신의 업무를 타인에게 포괄적으로 위임할 수 없다.","w":"대표자의 직무는 포괄적으로 위임할 수 없고, 특정 사항에 한해 대행하게 할 수 있을 뿐이다.","c":"상"},"변리사2018_55-07-5":{"f":"권리능력 없는 사단의 사원의 지위는 규약에 의하여 양도나 상속될 수 있다.","w":"사원의 지위는 규약이나 관행에 따라 양도·상속할 수 있다. 법인 아닌 사단의 사원 지위는 기본적으로 규약이 정하는 대로 따른다.","c":"중"},"변리사2018_55-09-1":{"f":"법인의 정관에 법인 대표권의 제한에 관한 규정이 있다면, 그러한 취지가 등기되어 있지 않은 경우에는 법인은 그 제한으로써 악의의 제3자에게도 대항할 수 없다.","w":"대표권 제한은 정관에 있어도 등기하지 않으면 제3자에게 대항하지 못하고, 제3자의 선의·악의를 묻지 않는다(민법 제60조).","c":"상"},"변리사2018_55-09-2":{"f":"법인의 정관에 이사의 해임사유에 관한 규정이 있는 경우에도 이사의 중대한 의무 위반이 있으면 법인은 정관에서 정하지 아니한 사유로 이사를 해임할 수 있다.","w":"법인과 이사의 관계는 위임 유사의 관계이므로, 이사에게 중대한 의무 위반 등이 있으면 정관에 정하지 않은 사유로도 해임할 수 있다(대법원 2013.11.28. 선고 판결).","c":"중"},"변리사2018_55-09-4":{"f":"이사의 임기가 만료되었더라도 아직 임기가 만료되지 아니한 다른 이사들로 법인이 정상적인 활동을 할 수 있는 경우에는 임기만료된 이사로 하여금 이사로서 직무를 행사하게 할 필요가 없고, 법인의 정상적인 활동이 가능한지 여부는 이사의 임기만료시를 기준으로 판단하여야 한다.","w":"후임 이사 선임 전 임기만료 이사의 직무수행이 필요한지는 임기만료 당시를 기준으로 법인이 정상 활동을 할 수 있는지에 따라 판단한다는 취지로 보이나, 판례 표현의 세부는 확신하지 못한다.","c":"하"},"변리사2018_55-09-5":{"f":"대표권 없는 이사의 행위로는 민법 제35조 소정의 법인의 불법행위가 성립하지 않는다.","w":"법인의 불법행위(제35조)는 대표기관의 행위로 성립한다. 대표권 없는 이사의 행위는 대표기관의 행위가 아니므로 제35조가 적용되지 않는다(대법원 2005.12.23. 선고 판결).","c":"중"},"변리사2018_55-10-4":{"f":"어떤 법률행위에 그 일상적인 의미만을 이해하여서는 알기 어려운 특별한 법률적인 의미나 효과가 부여되어 있는 경우에는 의사능력이 인정되기 위하여 그 행위의 일상적인 의미에 대한 이해만으로는 부족하고 법률적인 의미나 효과에 대한 이해도 필요하다.","w":"이런 법률행위에서는 일상적 의미뿐 아니라 법률적 의미와 효과를 이해할 수 있어야 의사능력이 인정된다(대법원 2006.9.22. 선고 판결).","c":"상"},"변리사2019_56-02-2":{"f":"甲은 법정대리인의 동의가 없었다는 이유로 자신이 체결한 매매계약을 원칙적으로 취소할 수 있다.","w":"17세의 미성년자가 법정대리인의 동의 없이 체결한 계약은 본인도 취소할 수 있다(민법 제5조 제2항).","c":"상"},"변리사2019_56-03-2":{"f":"사원자격의 득실에 관한 규정은 사단법인 정관의 필요적 기재사항에 해당한다.","w":"사원이 있는 것은 사단법인이다. 재단법인은 사원이 없으므로 사원자격 득실에 관한 사항은 재단법인 정관의 기재사항이 아니다(민법 제40조, 제43조).","c":"상"},"변리사2021_58-03-1":{"f":"비법인사단은 부동산소유권에 관하여 등기의무자가 될 수 있다.","w":"비법인사단은 사단 명의로 부동산등기를 할 수 있으므로 등기권리자·등기의무자가 될 수 있다(부동산등기법 제26조).","c":"상"},"변리사2021_58-03-3":{"f":"비법인사단의 대표자가 행한 타인에 대한 업무의 포괄적 위임과 그에 따른 포괄적 수임인의 대행행위는 비법인사단에 대하여 그 효력이 없다.","w":"대표자의 직무를 포괄적으로 위임하는 것은 허용되지 않아 그 대행행위는 사단에 효력이 미치지 않는다.","c":"상"},"변리사2021_58-03-4":{"f":"비법인사단의 채무는 사단에 귀속한다.","w":"비법인사단의 채무는 사단 자체에 귀속하고, 구성원이 지분비율에 따라 나누어 부담하지 않는다. 구성원은 사단의 채무에 개인 재산으로 책임지지 않는다.","c":"중"},"변리사2021_58-03-5":{"f":"이사의 결원으로 인하여 손해가 생길 염려가 있으면 이해관계인은 법원에 임시이사의 선임을 청구할 수 있다.","w":"이사가 없거나 결원이 되어 손해가 생길 염려가 있으면 이해관계인이나 검사의 청구로 법원이 임시이사를 선임할 수 있다(민법 제63조).","c":"상"},"변리사2023_60-02-1":{"f":"","w":"사례에서 甲이 성년이 된 뒤에도 취소권 행사기간(추인할 수 있은 날부터 3년, 법률행위를 한 날부터 10년) 안이면 매매계약을 취소할 수 있다. 사실관계 전체를 알 수 없어 정확한 결론은 사안 확인이 필요하다.","c":"하"},"변리사2023_60-03-3":{"f":"이사의 대표권에 대한 제한은 이를 등기하지 아니하면 제3자에게 대항하지 못한다.","w":"등기하지 않아도 당사자 사이에서는 효력이 있고, 등기하지 않으면 제3자에게 대항하지 못한다(민법 제60조). 효력 자체가 없는 것은 아니다.","c":"상"},"변리사2024_61-01-1":{"f":"채권자는 물상보증인이 되려는 자에게 주채무자의 신용상태를 조사해서 고지할 신의칙상 의무를 부담하지 않는다.","w":"채권자에게 물상보증인 될 사람에게 주채무자의 신용상태를 조사하여 알려줄 신의칙상 의무는 없다.","c":"상"},"변리사2026_63-02-1":{"f":"부재자로부터 재산의 처분권한을 위임받은 자는 부재자의 생사불명을 이유로 법원에 의해 부재자의 재산관리인으로 선임된 이후에는 부재자의 재산처분에 법원의 허가를 받아야 한다.","w":"법원이 재산관리인을 선임하면 그 재산관리인이 법원의 감독을 받으므로, 처분행위에는 법원의 허가가 필요하다(민법 제25조).","c":"중"},"변리사2026_63-02-3":{"f":"후순위상속인은 부재자에 대한 실종선고를 청구할 수 있는 이해관계인에 해당하지 않는다.","w":"실종선고 청구권자인 이해관계인은 법률상 직접 이해관계를 가진 사람이다. 후순위상속인은 실종선고 여부에 따라 상속지분이 달라져도 이해관계인이 아니다.","c":"상"},"변리사2026_63-02-4":{"f":"실종자를 당사자로 한 판결이 확정된 후에 실종선고가 확정되어 그 사망간주의 시점이 소제기 이전으로 소급하는 경우에도, 그 판결은 당연무효가 아니고 재심의 소로 다툴 수 있을 뿐이다.","w":"확정판결은 실종선고가 확정되어도 당연무효가 되지 않고, 재심으로 취소를 구하여야 한다.","c":"중"},"변리사2026_63-02-5":{"f":"실종선고가 이미 확정된 자에 대하여 그 실종선고가 취소됨이 없이 다시 실종선고가 내려진 경우, 최초의 실종선고를 기초로 상속관계를 판단하여야 한다.","w":"이미 확정된 실종선고가 취소되지 않았으면 그 선고가 기준이므로 상속관계는 처음의 실종선고에 따라 판단한다.","c":"중"},"변리사2026_63-03-1":{"f":"재단법인의 정관변경은 그 변경방법을 정관에서 정한 때에도 주무관청의 허가를 얻어야 효력이 있다.","w":"정관에서 변경방법을 정한 때에는 그 방법에 따르되, 효력이 생기려면 주무관청의 허가가 필요하다(민법 제45조 제3항, 제42조 제2항).","c":"상"},"변리사2026_63-03-3":{"f":"법인과 이사의 이익이 상반되는 사항에 관하여 이해관계인 또는 검사의 청구가 있는 경우, 법원은 특별대리인을 선임하여야 한다.","w":"이익이 상반되는 사항에는 임시이사(제63조)가 아니라 특별대리인을 선임한다(민법 제64조).","c":"상"},"변리사2026_63-03-4":{"f":"사원총회의 결의로 정관의 규범적 의미와 다른 해석이 표명된 경우에도, 그 결의에 의한 해석은 법원을 구속하지 않는다.","w":"정관의 규범적 의미 내용은 법원이 객관적으로 해석하며, 사원총회의 결의로 다르게 해석해도 법원이 구속되지 않는다.","c":"상"},"변리사2026_63-03-5":{"f":"청산 중인 법인의 청산인은 채권신고기간 내에는 채권자에 대한 변제를 할 수 없으나, 그 기간 동안에도 법인은 채권자에 대한 지연배상책임을 면하지 못한다.","w":"채권신고기간 중 변제를 못해도 법인은 채권자에 대한 지연배상책임을 면하지 못한다(민법 제90조 단서).","c":"상"},"변리사2016_53-04-3":{"f":"물건이 주물의 소유자의 상용에 공여되고 있더라도, 주물 그 자체의 효용과 직접 관계가 없는 것은 종물이 아니다.","w":"종물은 주물 자체의 효용에 이바지하는 물건이어야 한다. 소유자가 쓰고 있다는 것만으로는 종물이 되지 않는다(대법원 판례).","c":"상"},"변리사2017_54-04-2":{"f":"입목등기를 하지 않은 수목도 명인방법을 갖추면 독립된 물건이 될 수 있다.","w":"입목등기가 없는 수목은 명인방법을 갖추면 토지와 별개의 독립한 물건으로 거래할 수 있다.","c":"상"},"변리사2017_54-04-3":{"f":"주물 소유자의 사용에 공여되고 있는 물건이라도 주물 자체의 효용과 관계없는 물건이면 종물이 되지 않는다.","w":"종물이 되려면 주물의 상용에 이바지해야 하고, 소유자의 일반적 사용만으로는 부족하다.","c":"상"},"변리사2017_54-04-4":{"f":"성숙한 농작물은 명인방법을 갖추지 않아도 경작자의 소유가 된다.","w":"타인 토지에서 정당한 권원 없이 경작한 경우에도 농작물의 소유권은 경작자에게 있고, 명인방법은 필요 없다(대법원 판례).","c":"중"},"변리사2017_54-04-5":{"f":"토지등기부에 분필등기가 되어도 「공간정보의 구축 및 관리 등에 관한 법률」이 정하는 바에 따른 분할절차를 밟지 않으면 분필의 효과가 발생하지 않는다.","w":"토지의 분할은 지적공부 정리 등 법정 분할절차를 거쳐야 효력이 생기고, 분필등기만으로는 효과가 없다.","c":"상"},"변리사2018_55-12-2":{"f":"종물은 주물의 일부이거나 구성부분이 아니고 독립한 물건이어야 한다.","w":"주물의 구성부분은 종물이 아니다. 종물은 주물과 독립한 별개의 물건이다(민법 제100조 제1항).","c":"상"},"변리사2019_56-04-1":{"f":"소유권이전의 대가, 노동의 대가는 법정과실이 아니다.","w":"법정과실은 물건의 사용대가로 받는 금전 기타의 물건(임료·이자 등)이다. 소유권이전의 대가나 노동의 대가는 포함되지 않는다(민법 제101조 제2항).","c":"상"},"변리사2021_58-05-2":{"f":"집합물에 대한 양도담보권자가 점유개정의 방법으로 양도담보권설정계약 당시 존재하는 집합물의 점유를 취득한 후 양도담보권설정자가 자기 소유의 집합물을 이루는 물건을 반입한 경우, 나중에 반입된 물건에도 양도담보권의 효력이 미친다.","w":"집합물에 대한 양도담보는 계약 후 반입된 구성물에도 효력이 미친다(대법원 2004.11.12. 선고 판결).","c":"상"},"변리사2021_58-05-3":{"f":"적법한 경작권 없이 타인의 토지를 경작하였더라도 그 경작한 입도(立稻)가 성숙한 경우에는 경작자가 그 입도의 소유권을 가진다.","w":"성숙한 농작물은 독립한 물건이며, 경작권의 유무와 관계없이 경작한 사람에게 소유권이 있다(대법원 1979.8.28. 선고 판결).","c":"중"},"변리사2021_58-05-4":{"f":"종물은 주물의 처분에 따르지만, 당사자의 특약으로 종물만을 별도로 처분할 수 있다.","w":"종물은 주물의 처분에 따르는 것이 원칙이나 강행규정이 아니다. 특약으로 종물을 제외하거나 종물만 따로 처분할 수 있다(민법 제100조 제2항).","c":"상"},"변리사2021_58-05-5":{"f":"입목에 관한 법률에 의하여 소유권보존등기가 마쳐진 입목은 토지와 분리하여 양도될 수 있고, 저당권의 객체도 될 수 있다.","w":"등기된 입목은 부동산으로 보아 토지와 별개로 양도할 수 있고 저당권의 목적이 될 수 있다(입목에 관한 법률 제3조).","c":"상"},"변리사2024_61-04-1":{"f":"독립한 물건이라면 부동산도 종물이 될 수 있다.","w":"종물은 독립한 물건이면 동산이든 부동산이든 될 수 있다.","c":"중"},"변리사2024_61-04-2":{"f":"주물의 점유로 인한 시효취득의 효력은 점유하지 않은 종물에는 미치지 않는다.","w":"종물은 독립한 물건이므로 시효취득은 점유 요건을 갖춘 물건에만 생긴다. 점유하지 않은 종물까지 주물의 점유로 시효취득하지는 않는다.","c":"하"},"변리사2024_61-04-3":{"f":"주물에 대한 압류의 효력은 원칙적으로 종물에도 미친다.","w":"종물은 주물의 처분에 따르므로 주물에 대한 압류의 효력은 종물에도 미친다(민법 제100조 제2항 유추).","c":"중"},"변리사2024_61-04-4":{"f":"주물 그 자체의 효용과 직접 관계가 없는 한 주물의 소유자의 상용에 공여되고 있는 물건이라도 종물이 아니다.","w":"종물은 주물 자체의 효용에 이바지해야 하며, 소유자의 일반적인 사용에 쓰인다는 것만으로는 부족하다.","c":"상"},"변리사2016_53-05-1":{"f":"계약체결 당시 불공정한 법률행위가 아니라면 사후에 외부 환경의 급격한 변화로 계약당사자 일방에게 큰 손실이, 상대방에게는 그에 상응하는 큰 이익이 발생하더라도 불공정한 계약에 해당하지 않는다.","w":"불공정한 법률행위(제104조)는 계약 성립 당시를 기준으로 판단하고, 사후 사정변경은 판단 대상이 아니다(대법원 판례).","c":"상"},"변리사2016_53-06-5":{"f":"사기에 의한 의사표시의 취소로써 대항하지 못하는 선의의 제3자란 취소 전에 새로운 이해관계를 맺은 제3자를 말한다.","w":"제110조 제3항의 제3자는 취소의 의사표시가 있기 전에 새롭게 이해관계를 맺은 선의의 제3자이다. 취소 후에 이해관계를 맺은 자는 등기 등 대항요건 문제로 다룬다.","c":"하"},"변리사2016_53-08-1":{"f":"비법인사단인 교회의 대표자가 교인총회의 결의를 거치지 않고 총유물인 교회재산을 처분한 행위에 대하여는 민법 제126조(권한을 넘은 표현대리)를 준용할 수 없다.","w":"총유물 처분은 사원총회 결의가 필요하며, 이를 거치지 않은 대표자의 처분은 표현대리가 성립하지 않는다(대법원 2009.2.12. 선고 판결).","c":"상"},"변리사2016_53-10-1":{"f":"복대리인은 대리인이 선임한 본인의 대리인이다.","w":"복대리인은 대리인의 대리인이 아니라 본인의 대리인이다. 대리인이 자기 이름으로 선임하되 본인을 대리한다(민법 제123조).","c":"상"},"변리사2016_53-11-4":{"f":"조건을 붙이는 것이 허용되지 않는 법률행위에 조건을 붙인 경우 그 법률행위는 무효이다.","w":"조건과 친하지 않은 법률행위에 조건을 붙이면 조건만 무효가 되는 것이 아니라 그 법률행위 전체가 무효이다.","c":"상"},"변리사2017_54-07-5":{"f":"乙이 丙으로부터 받은 매매대금을 유용할 배임적 의도를 갖고 있었고 丙이 이를 알았다면, 민법 제107조 제1항 단서의 유추적용으로 乙의 대리행위는 甲에게 효력이 없다.","w":"대리권 남용을 상대방이 알았거나 알 수 있었던 경우에는 무권대리가 되는 것이 아니라 비진의표시 단서를 유추하여 본인에게 효력이 없다.","c":"중"},"변리사2017_54-08-3":{"f":"乙이 甲을 단독으로 상속하여 X토지의 소유자가 되면, 乙은 본인의 지위에서 매매계약의 추인을 거절할 수 없다.","w":"무권대리인이 본인을 상속한 경우 추인거절은 신의칙에 반하여 허용되지 않는다(대법원 1994.9.27. 선고 판결).","c":"상"},"변리사2019_56-05-1":{"f":"착오가 의사표시자의 중대한 과실로 인한 경우에도 상대방이 그 착오를 알고 이를 이용하였다면 의사표시자는 착오를 이유로 의사표시를 취소할 수 있다.","w":"중과실이 있어도 상대방이 착오를 알고 이용한 경우에는 취소할 수 있다(대법원 판례).","c":"중"},"변리사2019_56-05-3":{"f":"무효인 가등기를 유효한 등기로 전용할 것을 약정하였더라도 그 가등기가 소급하여 유효로 되는 것은 아니다.","w":"무효행위의 추인은 소급효가 없고, 가등기를 유효한 등기로 전용하는 약정이 있어도 그 효력은 약정 시부터 생긴다(대법원 1992.5.12. 선고 판결).","c":"상"},"변리사2019_56-05-4":{"f":"취소권을 행사할 수 있는 기간의 경과 여부는 제척기간이므로 법원이 직권으로 조사하여 고려해야 한다.","w":"취소권 행사기간은 제척기간이어서 당사자의 주장이 없어도 법원이 직권으로 조사한다.","c":"상"},"변리사2019_56-05-5":{"f":"유동적 무효인 토지거래계약이 확정적으로 무효가 된 경우, 이에 대해 귀책사유가 있는 자도 계약의 무효를 주장할 수 있다.","w":"확정적 무효가 된 이상 누구든 무효를 주장할 수 있고, 귀책사유가 있는 당사자도 마찬가지이다(대법원 1997.6.27. 전원합의체 판결).","c":"상"},"변리사2019_56-06-1":{"f":"공무원 甲이 사직의 의사표시를 하는 것과 같은 사인의 공법행위에는 진의 아닌 의사표시에 관한 민법 규정이 적용되지 않는다.","w":"사인의 공법행위에는 민법 제107조 단서가 적용되지 않는다. 사직서 제출 시 속마음이 달라도 효력이 있다.","c":"상"},"변리사2019_56-09-1":{"f":"乙이 무권대리인임을 알았던 丙도 甲에게 乙의 대리행위에 대한 추인 여부의 확답을 최고할 수 있다.","w":"최고권은 상대방의 선의·악의와 관계없이 인정된다(민법 제131조). 철회권만 선의의 상대방에게 있다.","c":"상"},"변리사2018_55-11-1":{"f":"복대리인은 본인의 대리인이다.","w":"복대리인은 대리인의 대리인이 아니라 본인의 대리인이다(민법 제123조 제1항).","c":"상"},"변리사2018_55-11-2":{"f":"임의대리인은 본인의 승낙이 있거나 부득이한 사유가 있는 때가 아니면 복대리인을 선임하지 못한다.","w":"임의대리인은 원칙적으로 복임권이 없고, 본인의 승낙이나 부득이한 사유가 있을 때에만 복대리인을 선임할 수 있다(민법 제120조).","c":"상"},"변리사2018_55-11-4":{"f":"법정대리인이 부득이한 사유로 복대리인을 선임한 경우에는 본인에 대하여 그 선임감독에 관한 책임만 있다.","w":"법정대리인은 자기 책임으로 복대리인을 선임할 수 있고, 부득이한 사유로 선임한 때에는 선임감독상의 책임만 진다(민법 제122조). 원문의 책임 범위는 본인이 지명한 경우의 임의대리인 책임 규정(제121조 제2항)에 해당한다.","c":"상"},"변리사2018_55-11-5":{"f":"대리인의 사망으로 대리권이 소멸한 경우에는 복대리권도 소멸한다.","w":"복대리권은 대리인의 대리권을 바탕으로 하므로 대리권이 소멸하면 복대리권도 소멸한다.","c":"상"},"변리사2019_56-11-3":{"f":"매매계약의 체결에 관한 권한을 수여받은 乙이 甲을 대리하여 매매계약을 체결한 경우, 乙은 특별한 사정이 없는 한 甲을 대리하여 매매계약의 해제 등 처분권을 행사할 수 없다.","w":"매매계약 체결 권한에는 중도금·잔금을 받는 이행 권한은 포함되지만, 계약 해제 같은 처분권은 포함되지 않는다.","c":"중"},"변리사2019_56-12-3":{"f":"조건이 법률행위 당시 이미 성취한 것인 경우에는 그 조건이 해제조건이면 그 법률행위는 무효로 한다.","w":"이미 성취한 조건이 정지조건이면 조건 없는 법률행위가 되고, 해제조건이면 그 법률행위는 무효이다(민법 제151조 제2항).","c":"상"},"변리사2021_58-04-3":{"f":"무상임치의 경우에는 임치인(채권자)만이, 무이자 소비대차의 경우에는 채무자만이 기한이익을 갖는다.","w":"무상임치에서는 임치인이 기한 전에도 언제든 반환을 청구할 수 있어 기한이익이 채무자인 수치인에게 없다(민법 제698조). 기한이익이 채무자에게 있다는 추정(제153조 제1항)은 무상임치에는 맞지 않는다.","c":"중"},"변리사2021_58-07-2":{"f":"불공정한 법률행위로서 무효인 경우에는 추인하여도 유효로 되지 않는다.","w":"불공정한 법률행위는 절대적 무효이므로 추인해도 유효가 되지 않는다.","c":"상"},"변리사2021_58-07-3":{"f":"불공정한 법률행위에 관한 규정은 부담 없는 증여의 경우에는 적용되지 않는다.","w":"대가관계 없이 일방적으로 급부하는 부담 없는 증여에는 제104조가 적용되지 않는다(대법원 2000.2.11. 선고 판결).","c":"상"},"변리사2021_58-07-4":{"f":"경매에서 경매부동산의 매각대금이 시가에 비하여 현저히 저렴한 경우에도, 불공정한 법률행위에 해당하지 않는다.","w":"경매에는 불공정한 법률행위 규정이 적용되지 않는다. 경매는 법률행위가 아니라 국가기관이 행하는 절차이다(대법원 1980.3.21. 자 결정).","c":"상"},"변리사2021_58-07-5":{"f":"법률행위가 현저하게 공정을 잃은 경우에도, 그 법률행위가 궁박·경솔·무경험으로 인해 이루어진 것으로 추정되지 않는다.","w":"급부와 반대급부 사이의 현저한 불균형이 있다고 해서 궁박·경솔·무경험이 추정되지 않는다. 이 요건은 주장하는 쪽이 증명해야 한다(대법원 판례).","c":"상"},"변리사2021_58-08-1":{"f":"법률에 관한 착오도 그것이 법률행위 내용의 중요부분에 관한 것이라면 착오를 이유로 취소할 수 있다.","w":"법률의 부지·착오도 법률행위 내용의 중요부분에 관한 것이면 취소할 수 있다(대법원 판례).","c":"상"},"변리사2021_58-08-2":{"f":"착오로 인한 의사표시의 취소에 관한 민법 제109조 제1항은 당사자의 합의로 그 적용을 배제할 수 있다.","w":"제109조 제1항은 임의규정이어서 당사자 합의로 배제할 수 있다.","c":"상"},"변리사2021_58-08-3":{"f":"착오한 표의자의 중대한 과실 유무에 관한 증명책임은 의사표시의 효력을 부인하려는 상대방에게 있다.","w":"표의자의 중대한 과실은 취소를 막으려는 상대방이 증명한다.","c":"상"},"변리사2021_58-08-5":{"f":"표의자가 착오를 이유로 의사표시를 취소한 경우, 취소로 인하여 손해를 입은 상대방은 표의자에게 불법행위로 인한 손해배상을 청구할 수 없다.","w":"착오가 경과실에 그치는 표의자가 취소권을 행사한 것은 위법하지 않으므로, 상대방은 취소로 입은 손해를 불법행위로 청구할 수 없다.","c":"중"},"변리사2021_58-09-3":{"f":"丙과의 매매계약이 불공정한 법률행위에 해당하는지 여부가 문제된 경우, 매도인의 무경험은 대리인 乙을 기준으로 판단한다.","w":"대리인이 계약을 체결한 경우 경솔·무경험은 대리인을 기준으로, 궁박은 본인을 기준으로 판단한다(대법원 판례).","c":"중"},"변리사2021_58-10-1":{"f":"제한능력자의 법률행위에 대한 법정대리인의 추인은 취소의 원인이 소멸되기 전에도 그 효력이 있다.","w":"취소의 원인이 소멸된 후에 추인해야 한다는 요건은 취소권자가 제한능력자 본인일 때의 것이고, 법정대리인의 추인에는 이 요건이 필요 없다(민법 제144조 제2항).","c":"상"},"변리사2021_58-11-5":{"f":"X토지가 중간생략등기의 합의에 따라 乙로부터 丙에게 허가 없이 전매된 경우, 丙은 甲에 대하여 직접 허가신청절차의 협력의무 이행청구권을 가지지 못한다.","w":"토지거래허가구역 내에서 전매하는 중간생략등기 합의는 허가 대상이다. 최종 매수인 丙은 최초 매도인 甲에게 직접 협력의무 이행을 청구할 수 없다(대법원 1991.12.24. 전원합의체 판결).","c":"상"},"변리사2021_58-12-1":{"f":"丙이 乙의 대리행위가 유권대리라고 주장하는 경우, 그 주장 속에는 표현대리의 주장이 포함된 것으로 볼 수 없다.","w":"유권대리와 표현대리는 별개의 요건사실이어서, 유권대리 주장에 표현대리 주장이 당연히 포함되지 않는다(대법원 1983.12.13. 전원합의체 판결).","c":"상"},"변리사2021_58-12-3":{"f":"丙이 계약체결 당시에 乙에게 매매계약 체결의 대리권이 없음을 알았다면 계약을 철회할 수 없다.","w":"상대방의 철회권은 계약 당시 대리권 없음을 몰랐던 선의의 상대방에게만 있다(민법 제134조).","c":"상"},"변리사2021_58-12-4":{"f":"乙의 행위가 권한을 넘은 표현대리로 인정되는 경우, 丙에게 과실(過失)이 있더라도 과실상계의 법리에 따라 甲의 책임이 경감될 수는 없다.","w":"표현대리가 성립하면 본인은 전부 책임을 지며, 상대방의 과실을 이유로 책임을 줄일 수 없다(대법원 1996.7.12. 선고 판결).","c":"상"},"변리사2021_58-12-5":{"f":"丙이 乙의 대리행위가 권한을 넘은 표현대리라고 주장하는 경우, 乙에게 매매계약체결의 대리권이 있다고 丙이 믿을 만한 정당한 이유가 있었는지의 여부는 계약성립 당시의 모든 사정을 고려하여 판단해야 한다.","w":"정당한 이유는 대리행위가 이루어진 당시를 기준으로 판단하고, 계약성립 이후의 사정은 고려하지 않는다.","c":"상"},"변리사2023_60-08-4":{"f":"통정허위표시에 따른 선급금 반환채무 부담행위에 기하여 선의로 그 채무를 보증한 자는 보증채무를 이행하기 전에는 허위표시의 무효로부터 보호받는 제3자에 해당하지 않는다.","w":"보증인이 허위표시의 무효로부터 보호받는 제3자인지는 보증채무 이행 여부에 따라 달라진다는 취지로 보이나, 판례 세부는 확신하지 못한다.","c":"하"},"변리사2023_60-09-5":{"f":"예술품의 위작(僞作)을 진품으로 착각한 매도인의 말을 믿고서 과실 없이 진품에 상응하는 가격으로 그 위작을 구입한 매수인이 매도인에게 하자담보책임을 물을 수 있더라도 착오취소를 주장할 수 있다.","w":"하자담보책임과 착오취소는 요건이 달라 경합하며, 하자담보책임을 물을 수 있어도 착오를 이유로 취소할 수 있다(대법원 2018.9.13. 선고 판결).","c":"상"},"변리사2023_60-10-1":{"f":"대리권은 대리인의 권리도 의무도 아니다.","w":"대리권은 대리인이 본인을 위해 행위하여 그 효과를 본인에게 귀속시킬 수 있는 법률상의 지위(자격)이다. 권리나 의무가 아니다.","c":"상"},"변리사2023_60-10-3":{"f":"복대리인은 본인의 대리인이지만 원대리인의 복임행위는 본인을 위한 대리행위가 아니다.","w":"복임행위는 대리인이 자기 권한으로 복대리인을 선임하는 행위이며 본인을 대리하는 행위가 아니다. 복대리인의 선임은 대리인 자신의 행위이다.","c":"상"},"변리사2023_60-10-4":{"f":"대리권이 이미 소멸한 원대리인에 의해 선임된 복대리인의 대리행위에 대해서도 대리권 소멸 후의 표현대리(제129조)가 성립할 여지가 있다.","w":"복대리인이 한 행위에도 제129조가 적용될 수 있다(대법원 1998.5.29. 선고 판결).","c":"상"},"변리사2023_60-10-5":{"f":"자신에게 유효한 대리권이 있다고 과실 없이 믿었던, 행위능력 있는 선의의 무권대리인도 본인의 추인이 없다면 상대방에 대한 무권대리인의 책임에 관한 민법 제135조에 따른 책임을 진다.","w":"제135조의 무권대리인 책임은 무과실책임이다. 자신에게 대리권이 있다고 믿은 데 과실이 없어도 책임을 진다(대법원 판례). 행위능력이 없는 경우만 면책된다.","c":"상"},"변리사2023_60-11-5":{"f":"乙은 특별한 사정이 없는 한 위 매매계약의 허가를 받기 전까지는 부당이득반환청구권을 행사하여 甲에게 이미 지급한 계약금의 반환을 청구할 수 없다.","w":"허가를 받기 전 유동적 무효 상태에서는 계약이 확정적으로 무효가 되기 전이므로 부당이득으로 반환을 청구할 수 없다(대법원 1997.6.27. 전원합의체 판결).","c":"상"},"변리사2023_60-12-1":{"f":"이행지체의 경우 채권자는 채무자를 상대로 상당한 기간을 정하여 이행을 청구하면서 그 기간 내에 이행이 없으면 계약은 당연히 해제된 것으로 한다는 취지의 정지조건부 해제권 행사를 할 수 있다.","w":"이행 최고와 함께 기간 내 이행하지 않으면 해제된 것으로 한다는 의사표시는 정지조건부 해제의 의사표시로서 유효하다. 해제조건부로 보지 않는다.","c":"중"},"변리사2024_61-06-2":{"f":"매매목적물에 하자가 있는 사실을 착오로 알지 못하고 매매계약을 체결한 매수인은 착오로 인한 의사표시의 취소 요건을 갖춘 경우 매도인의 하자담보책임이 성립하더라도 착오를 이유로 그 계약을 취소할 수 있다.","w":"하자담보책임과 착오취소는 경합할 수 있어, 하자담보책임을 물을 수 있어도 착오취소가 가능하다(대법원 2018.9.13. 선고 판결).","c":"상"},"변리사2024_61-07-3":{"f":"적법하게 성립된 매매에 관하여 해제사유가 발생한 경우, 해제의 의사가 상대방 당사자의 미성년 자(子)에게 도달하더라도 그 즉시 해제의 효력이 발생하지는 않는다.","w":"상대방이 의사표시를 받은 때 제한능력자이면 표의자는 그 의사표시로 대항하지 못한다. 법정대리인이 안 때부터 효력이 생긴다(민법 제112조).","c":"상"},"변리사2024_61-08-1":{"f":"법정대리인은 원칙적으로 부득이한 사유가 없어도 복임권이 있다.","w":"법정대리인은 부득이한 사유가 없어도 자기 책임으로 복대리인을 선임할 수 있다(민법 제122조).","c":"상"},"변리사2024_61-09-5":{"f":"만일 丙이 丁에게 위 부동산을 매도한 경우, 乙이 丁에게만 추인의 의사를 표시하더라도 추인의 효력은 발생한다.","w":"추인은 무권대리인이나 상대방, 상대방의 승계인에게 할 수 있다(대법원 1981.4.14. 선고 판결).","c":"상"},"변리사2024_61-10-1":{"f":"미성년자가 체결한 계약이 법정대리인의 동의없음을 이유로 취소할 수 있는 경우, 계약당사자인 미성년자는 단독으로 그 계약을 취소할 수 있다.","w":"미성년자 본인도 법정대리인의 동의 없이 단독으로 취소할 수 있다(민법 제5조 제1항 단서, 제140조).","c":"상"},"변리사2024_61-10-2":{"f":"계약을 체결할 수 있는 권한만을 가진 임의대리인이 상대방의 사기로 계약을 체결한 경우, 그 임의대리인은 별도의 수권 없이 그 계약을 취소할 수 없다.","w":"취소권은 계약 체결 대리권에 당연히 포함되지 않고, 취소 수권을 따로 받아야 한다. 취소권은 본인에게 속한다.","c":"중"},"변리사2024_61-10-3":{"f":"미성년자인 임의대리인이 계약을 체결한 경우, 본인은 미성년자에 의한 대리행위라는 이유로 취소할 수 없다.","w":"대리인은 행위능력자일 필요가 없으므로 본인은 대리인이 제한능력자임을 이유로 대리행위를 취소할 수 없다(민법 제117조).","c":"상"},"변리사2024_61-10-5":{"f":"미성년자가 단독으로 발급받은 신용카드를 이용하여 구입한 물품의 대금을 성년자가 되어 이의없이 결제한 후에는 그 물품구입계약을 미성년자의 행위임을 이유로 취소할 수 없다.","w":"성년이 된 뒤 이의 없이 대금을 이행하면 법정추인이 되어 취소할 수 없다(민법 제145조 제1호).","c":"상"},"변리사2024_61-11-1":{"f":"乙은 甲을 상대로 허가가 나오는 것을 조건으로 하여 잔금과 상환으로 이전등기를 해 달라고 청구할 수 없다.","w":"토지거래허가를 받기 전에는 채권적 효력도 없으므로 이행청구가 허용되지 않는다. 허가를 조건으로 한 장래이행청구도 안 된다(대법원 1991.12.24. 전원합의체 판결).","c":"상"},"변리사2024_61-11-2":{"f":"허가가 나오기 전에는 甲은 乙이 잔금기일에 잔금을 지급하지 않았다는 것을 이유로 위 계약을 해제할 수 없다.","w":"허가 전에는 유동적 무효 상태여서 채무불이행을 이유로 계약을 해제할 수 없다.","c":"상"},"변리사2024_61-11-4":{"f":"거래허가를 신청하기 전이라도 乙의 기망행위로 위 계약을 체결하였다면 甲은 그 계약을 취소할 수 있다.","w":"유동적 무효 상태에서도 사기에 의한 취소는 가능하며, 허가 신청 전에 취소하여 협력의무를 면할 수 있다(대법원 1997.11.14. 선고 판결).","c":"상"},"변리사2024_61-11-5":{"f":"만일 계약 당시 합의에 따라 계약금을 乙이 丙에게 지급하였는데 그 후 위 계약이 확정적으로 무효가 된 경우, 특별한 사정이 없는 한 乙은 甲을 상대로 지급한 계약금 상당액의 반환을 청구할 수 있다.","w":"제3자에게 급부한 경우 부당이득반환은 급부를 받은 제3자가 아니라 계약 상대방에게 청구한다. 급부관계는 乙과 甲 사이에 있다.","c":"하"},"변리사2026_63-05-3":{"f":"불공정한 법률행위로 무효인 경우, 당사자가 이를 추인하더라도 무효인 법률행위가 유효로 되지 않는다.","w":"불공정한 법률행위는 추인해도 유효가 되지 않는다. 무효행위의 추인(제139조)은 새로운 법률행위로 보는 경우에만 의미가 있다.","c":"상"},"변리사2026_63-06-4":{"f":"매도인이 제3자의 기망행위에 의해 매수인과 매매계약을 체결한 경우, 매도인이 그 제3자에게 사기에 의한 불법행위를 이유로 손해배상을 청구하기 위해서는 그 매매계약을 취소할 필요가 없다.","w":"사기 취소와 불법행위 손해배상은 별개이므로 매매계약을 취소하지 않고도 제3자에게 손해배상을 청구할 수 있다(대법원 판례).","c":"중"},"변리사2026_63-08-2":{"f":"권한을 넘은 표현대리는 특별한 사정이 없는 한, 대리인이 사술을 써서 대리행위의 표시없이 단지 본인의 성명을 모용하여 자기가 마치 본인인 것처럼 기망하여 본인 명의로 직접 법률행위를 한 경우에는 성립될 수 없다.","w":"이 경우 상대방은 대리인과 법률행위를 한다고 인식하지 않았으므로 표현대리가 성립하지 않는다(대법원 1993.2.12. 선고 판결).","c":"상"},"변리사2026_63-08-3":{"f":"대리권 소멸 후의 표현대리에 관한 민법 제129조는 법정대리인의 대리권 소멸에 관하여서도 적용될 수 있다.","w":"제129조는 임의대리뿐 아니라 법정대리에도 적용된다(대법원 1975.1.28. 선고 판결).","c":"상"},"변리사2026_63-08-4":{"f":"지방자치단체가 사경제주체로서 한 법률행위에 대해서는 표현대리에 관한 법리가 적용될 수 있다.","w":"사경제주체로서 하는 거래에서는 사인과 마찬가지로 표현대리 법리가 적용된다.","c":"중"},"변리사2026_63-08-5":{"f":"학교법인을 대표하는 이사장이 사립학교법상 규정을 위반하여 이사회의 심의결정없이 학교법인의 기본재산을 처분하는 행위에 대해서는 권한을 넘은 표현대리에 관한 규정이 준용될 수 없다.","w":"법령상 이사회 심의결정이 필요한 행위를 거치지 않은 처분에는 표현대리 규정을 준용할 수 없다(대법원 판례).","c":"중"},"변리사2026_63-09-2":{"f":"甲이 丙에게 계약을 이미 추인하였다면, 丙이 계약체결 당시 乙이 무권대리인임을 알지 못하였더라도 丙은 계약을 철회할 수 없다.","w":"상대방의 철회는 본인이 추인하기 전에만 가능하다(민법 제134조).","c":"상"},"변리사2016_53-12-1":{"f":"형성권은 제척기간의 경과 자체만으로 곧 권리 소멸의 효과가 발생한다.","w":"제척기간은 기간 경과 자체로 권리가 소멸하고, 소멸시효와 달리 당사자의 원용이 필요 없다.","c":"상"},"변리사2017_54-11-4":{"f":"A호텔의 청구에 대하여 기각판결이 확정된 후, A호텔이 재심을 청구하더라도 소멸시효의 진행이 중단되지 않는다.","w":"기각된 때에는 재판상 청구로 인한 시효중단의 효력이 없다(민법 제170조 제1항).","c":"중"},"변리사2017_54-12-2":{"f":"채권자가 채무자를 상대로 법원에 신청한 화해가 불성립되어 채권자가 그로부터 1월내에 소를 제기한 경우, 채권의 소멸시효는 화해신청 시부터 중단된다.","w":"화해신청 시에 시효가 중단되며, 불성립 후 1월 내에 소를 제기하면 그 효력이 유지된다(민법 제173조).","c":"상"},"변리사2017_54-12-3":{"f":"소멸시효의 기간만료 전 6월 내에 제한능력자에게 법정대리인이 없는 경우, 그가 능력자가 되거나 법정대리인이 취임한 때로부터 6월 내에는 소멸시효가 완성되지 아니한다.","w":"기간은 6개월이다(민법 제179조). 1년이 아니다.","c":"상"},"변리사2017_54-12-4":{"f":"상속재산에 대한 권리는 상속인의 확정, 관리인의 선임 또는 파산선고가 있는 때로부터 6월 내에는 소멸시효가 완성되지 아니한다.","w":"기간은 6개월이다(민법 제181조).","c":"상"},"변리사2017_54-12-5":{"f":"채무자가 시효중단의 효력이 있는 승인을 하는 데에는 채권자의 채권에 관한 처분의 능력이나 권한이 있을 것을 요하지 않는다.","w":"승인에는 상대방의 권리에 관한 처분의 능력이나 권한이 필요 없다(민법 제177조). 승인하는 채무자에게는 관리의 능력이나 권한만 있으면 된다.","c":"상"},"변리사2018_55-01-1":{"f":"부작위채권도 소멸시효의 대상이 된다.","w":"부작위채권도 위반행위가 있을 때부터 소멸시효가 진행한다.","c":"상"},"변리사2018_55-01-2":{"f":"주채무자가 시효완성의 이익을 포기한 경우에도 보증인은 주채무의 시효소멸을 원용할 수 있다.","w":"시효이익의 포기는 상대적 효력만 있어 포기한 사람에게만 미치고, 보증인은 별도로 원용할 수 있다(대법원 판례).","c":"상"},"변리사2018_55-01-3":{"f":"“시효의 중단은 당사자 및 그 승계인 간에만 효력이 있다”는 규정(민법 제169조)에서 ‘승계인’에는 특정승계인이 포함된다.","w":"제169조의 승계인에는 포괄승계인뿐 아니라 특정승계인도 포함된다.","c":"상"},"변리사2018_55-01-4":{"f":"기한을 정하지 않은 채권의 소멸시효의 기산점은 이행청구를 받은 때가 아니라 채권이 발생된 때이다.","w":"기한 없는 채권은 성립한 때부터 언제든 청구할 수 있으므로 그때부터 소멸시효가 진행한다(민법 제166조 제1항).","c":"상"},"변리사2019_56-08-1":{"f":"제척기간이 경과하면 그 기산일에 소급하여 권리소멸의 효과가 발생하지 않는다.","w":"소멸시효와 달리 제척기간은 기간이 지난 때에 권리가 소멸하고 기산일로 소급하지 않는다.","c":"중"},"변리사2019_56-08-2":{"f":"제척기간은 권리자의 청구나 압류 등이 있어도 중단되지 않는다.","w":"제척기간에는 중단이 없다. 소멸시효에만 중단·정지 제도가 있다.","c":"상"},"변리사2019_56-08-3":{"f":"점유보호청구권의 행사기간은 제척기간이기 때문에 반드시 그 기간 내에 소를 제기하여야 한다.","w":"점유보호청구권의 행사기간은 출소기간이어서 재판 외 행사로는 부족하고 기간 내에 소를 제기해야 한다.","c":"상"},"변리사2019_56-08-5":{"f":"채권양도의 통지만으로는 제척기간의 준수에 필요한 권리의 재판 외 행사가 이루어졌다고 볼 수 없다.","w":"채권양도 통지는 양도 사실을 알리는 관념의 통지일 뿐, 채무자에게 채권의 이행을 청구하는 권리 행사가 아니다.","c":"중"},"변리사2019_56-10-3":{"f":"甲이 乙을 상대로 대여금반환청구의 소를 제기하였다가 이후 그 소를 취하한 경우에는 甲의 대여금반환청구의 소제기로 인한 시효중단의 효력이 없다.","w":"소를 취하하면 시효중단의 효력이 생기지 않는다(민법 제170조 제1항 유추). 다만 6개월 내 다시 소를 제기하거나 압류 등을 하면 최초 소 제기 시에 중단된 것으로 본다(제170조 제2항).","c":"상"},"변리사2019_56-15-5":{"f":"소유권이전등기의 말소를 구하는 소를 제기하였다가 그 소를 취하한 후, 그로부터 6개월 내에 다시 취하된 소와 동일한 내용의 소를 제기한 경우, 최초의 소가 제기된 때로부터 취득시효의 진행이 중단된다.","w":"6개월 내에 다시 소를 제기하면 최초의 재판상 청구 때 중단된 것으로 본다(민법 제170조 제2항). 후소 제기 시가 아니다.","c":"중"},"변리사2021_58-06-5":{"f":"원인채권의 지급을 확보하기 위하여 어음이 수수된 당사자 사이에 채권자가 어음채권에 관한 집행권원에 기하여 한 배당요구는 그 원인채권의 소멸시효를 중단시키는 효력이 있다.","w":"배당요구는 압류에 준하는 시효중단 사유이며, 어음채권에 의한 배당요구가 원인채권의 시효도 중단시킨다.","c":"중"},"변리사2023_60-05-2":{"f":"2004년 1월 17일 오후 2시에 태어난 甲이 성년이 되는 시점은 2023년 1월 16일 24시이다.","w":"나이는 출생일을 산입하여 계산하므로(민법 제158조) 만 19세가 되는 날은 출생일 전날 24시이다.","c":"상"},"변리사2024_61-12-3":{"f":"채무자가 채권자를 상대로 채무부존재확인소송을 제기하여 채권자가 이를 적극적으로 다툰 경우, 채권자가 응소하여 적극적으로 권리를 주장한 때부터 시효중단의 효력이 인정된다.","w":"채무자가 제기한 소 자체는 시효를 중단시키지 않는다. 채권자가 응소하여 적극적으로 권리를 주장하여 받아들여졌을 때 재판상 청구로서 중단된다(대법원 1993.12.21. 전원합의체 판결).","c":"상"},"변리사2018_55-19-2":{"f":"乙의 甲에 대한 본등기청구권은 乙의 가등기가 존속하는 동안에도 소멸시효에 걸린다.","w":"가등기가 있어도 본등기청구권은 채권적 청구권이므로 소멸시효에 걸린다(대법원 판례).","c":"상"},"변리사2018_55-19-4":{"f":"乙이 가등기에 기한 본등기를 하면, 乙의 소유권취득의 효력은 본등기를 한 때부터 생긴다.","w":"본등기의 물권변동 효력은 본등기 시에 생기고 가등기 시로 소급하지 않는다. 가등기는 본등기의 순위만 보전한다.","c":"상"},"변리사2018_55-19-5":{"f":"丙 명의의 소유권이전등기가 원인무효라도 가등기권리자인 乙은 직접 그 말소를 구할 수 없다.","w":"가등기권리자는 아직 소유권자가 아니어서 제3자의 등기에 대한 말소청구권이 없고, 소유자를 대위하여 청구하는 방법을 취해야 한다.","c":"중"},"변리사2019_56-14-4":{"f":"후순위 저당권이 있는 부동산의 소유권을 선순위 저당권자가 아무런 조건 없이 증여 받아 취득한 경우에도 혼동에 의해 저당권은 소멸하지 않는다.","w":"다른 사람의 권리의 목적이 되어 있는 때에는 혼동으로 소멸하지 않는다(민법 제191조 제1항 단서). 후순위 저당권자의 이익이 있기 때문이다.","c":"상"},"변리사2021_58-15-1":{"f":"본등기에 의한 물권변동의 효력은 본등기를 한 때부터 발생한다.","w":"가등기는 순위만 보전하고, 본등기를 한 때에 물권변동 효력이 생긴다.","c":"상"},"변리사2021_58-15-3":{"f":"합유자가 그 지분을 포기하면 지분권 이전등기를 하여야 포기된 합유지분이 나머지 잔존 합유지분권자들에게 귀속된다.","w":"합유지분 포기에 의한 물권변동은 법률행위에 의한 변동이므로 등기가 있어야 효력이 생긴다(민법 제186조).","c":"상"},"변리사2021_58-15-4":{"f":"매매로 인한 소유권이전등기에서 등기명의자가 등기원인을 증여로 주장하더라도 등기의 추정력은 깨어지지 않는다.","w":"등기원인이 다르다고 주장해도 추정력은 유지된다. 새 원인이 부적법함을 증명해야 추정이 깨진다.","c":"중"},"변리사2021_58-15-5":{"f":"사망자 명의로 신청하여 이루어진 이전등기에는 등기의 추정력이 인정되지 않으므로, 그 등기의 유효를 주장하는 자가 실체관계에 부합함을 증명하여야 한다.","w":"사망자 명의 신청으로 이루어진 등기는 원인무효로서 추정력이 없다(대법원 판례).","c":"상"},"변리사2021_58-16-4":{"f":"甲은 丙에 대하여 간접점유자로서 점유권에 기한 방해배제청구권을 행사할 수 있다.","w":"간접점유자도 점유권에 기한 방해배제를 청구할 수 있다(민법 제207조). 소유자도 소유권에 기한 청구가 가능하다.","c":"중"},"변리사2023_60-14-1":{"f":"미등기건물에 대한 양도담보계약상의 채권자의 지위를 승계하여 건물을 관리하고 있는 자는 그 건물에 대한 철거처분권을 가진 자에 해당하지 않는다.","w":"미등기건물의 양도담보 채권자는 소유권을 취득하지 못하고 철거처분권도 없다.","c":"중"},"변리사2026_63-14-3":{"f":"토지에 대한 점유취득시효가 완성된 후 점유자가 그 토지에 대한 점유를 상실하더라도 시효완성을 원인으로 한 소유권이전등기청구권이 즉시 소멸하는 것은 아니다.","w":"시효완성 후 점유를 상실해도 이전등기청구권은 곧바로 소멸하지 않고, 별도의 소멸시효(10년)에 걸린다.","c":"상"},"변리사2026_63-17-4":{"f":"유치권자가 유치권을 포기하기로 한 경우, 유치물을 채무자에게 인도하지 않아도 포기의 의사표시로 그 유치권이 소멸한다.","w":"유치권은 포기의 의사표시만으로 소멸하고, 유치물을 반환하지 않아도 된다.","c":"중"},"변리사2017_54-13-5":{"f":"미등기 부동산의 경우에도 점유자는 취득시효기간이 완성된 후 등기를 하여야 소유권을 취득한다.","w":"점유취득시효는 기간이 완성되어도 등기를 해야 소유권을 취득한다(민법 제245조 제1항).","c":"상"},"변리사2018_55-14-1":{"f":"甲이 그 소유건물을 乙에게 임대하여 현실적으로 건물이나 그 부지를 점거하고 있지 않더라도, 甲은 그 부지를 점유한다고 볼 수 있다.","w":"건물 소유자는 건물을 임대한 경우에도 임차인을 통해 부지를 간접점유한다.","c":"상"},"변리사2018_55-17-1":{"f":"취득시효 완성 후 등기 경료 전에 그 부동산이 제3자에게 명의신탁된 경우, 점유자는 시효완성을 이유로 그 제3자의 소유권 행사를 저지할 수 있다.","w":"명의신탁에서는 실질 소유자가 따로 있어 제3자가 진정한 양수인이 아니고, 점유자의 취득시효를 주장하는 데 지장이 없다.","c":"하"},"변리사2018_55-17-3":{"f":"甲의 취득시효 완성 당시 미등기로 남아 있던 토지의 소유자가 취득시효 완성 후에 그 명의로 소유권보존등기를 마쳤더라도, 甲은 토지소유자에 대하여 취득시효의 완성을 주장할 수 있다.","w":"보존등기는 소유자의 변경이 아니므로 취득시효 완성 당시의 소유자에게 계속 주장할 수 있다.","c":"상"},"변리사2018_55-17-4":{"f":"국유재산이 일반재산이던 당시에 취득시효가 완성되었더라도 그 후 행정재산으로 되었다면 시효취득을 원인으로 하는 소유권이전등기를 청구할 수 없다.","w":"등기 전 행정재산이 되면 취득시효를 이유로 한 소유권이전이 허용되지 않는다(대법원 판례).","c":"중"},"변리사2018_55-17-5":{"f":"점유자가 취득시효기간이 경과한 후 소유자와의 분쟁을 간편하게 해결하기 위하여 상대방에게 매수제의를 하였더라도, 점유자의 점유는 타주점유로 전환되지 않는다.","w":"매수제의는 자주점유를 포기한 것이 아니고, 취득시효 완성 후 점유 성질은 달라지지 않는다.","c":"상"},"변리사2018_55-20-2":{"f":"반환청구권의 양도에 의한 소유권의 양도의 경우에는 대항요건을 갖추면 선의취득이 인정될 수 있다.","w":"반환청구권의 양도(지시인도)도 점유 취득의 한 방법으로 선의취득이 인정된다. 점유개정만 제외된다.","c":"중"},"변리사2018_55-20-3":{"f":"甲이 자신의 소유 동산을 乙에게 매도하여 인도하고, 乙이 다시 丙에게 매도하여 인도한 경우, 甲과 乙의 매매가 사회질서에 반하여 무효라도 丙은 선의, 무과실이라면 선의취득할 수 있다.","w":"乙은 점유를 가진 무권리자이므로 乙에서 丙으로의 거래에서는 선의취득이 가능하다.","c":"상"},"변리사2018_55-20-4":{"f":"점유보조자가 횡령한 물건은 민법 제250조(도품, 유실물에 대한 특례)의 도품에 해당하지 않는다.","w":"점유보조자의 횡령은 도품·유실물에 해당하지 않아 제250조가 적용되지 않는다.","c":"중"},"변리사2018_55-20-5":{"f":"甲 소유 동산을 점유하는 乙이 丙에게 매도함과 동시에 丙으로부터 임차하기로 약정한 경우 丙은 현실인도를 받기 전에는 그 동산을 선의취득할 수 없다.","w":"점유개정으로는 선의취득에 필요한 점유취득이 이루어지지 않는다(대법원 판례).","c":"상"},"변리사2018_55-22-5":{"f":"공유자 중 1인이 다른 공유자의 동의 없이 공유토지 전부를 매도하여 타인 명의로 소유권이전등기가 마쳐진 경우, 다른 공유자는 자기 지분에 관해서만 소유권이전등기의 말소를 청구할 수 있다.","w":"다른 공유자는 자기 지분에 해당하는 범위에서 말소를 청구한다.","c":"상"},"변리사2019_56-13-5":{"f":"","w":"사례의 사실관계를 알 수 없어 정확한 결론을 확인할 수 없다.","c":"하"},"변리사2021_58-13-5":{"f":"점유보조자가 보관한 물건을 횡령하여 형사상 절도죄가 성립되는 경우에도, 그 물건은 민법 제250조(도품유실물에 대한 특례)의 도품에 해당하지 않는다.","w":"점유보조자의 횡령은 도품이 아니어서 피해자는 2년 내 반환청구권을 갖지 못한다.","c":"중"},"변리사2023_60-15-2":{"f":"甲의 통상의 필요비 청구가 부정되는 민법 제203조(점유자의 상환청구권) 제1항 단서 규정은 과실수취권이 없는 악의의 점유자에 대해서는 적용되지 않는다.","w":"제203조 제1항 단서는 과실을 취득한 점유자에게 적용된다. 과실수취권이 없는 악의의 점유자는 통상의 필요비를 청구할 수 있다.","c":"상"},"변리사2023_60-15-3":{"f":"민법 제203조(점유자의 상환청구권) 제2항에서 유익비의 상환범위는 지출금액이나 증가액 중 회복자의 선택에 따른다.","w":"유익비는 점유자가 지출한 금액이나 현존하는 증가액 중 회복자가 선택하는 것으로 상환한다(민법 제203조 제2항).","c":"상"},"변리사2023_60-15-4":{"f":"점유물이 甲의 책임있는 사유로 인하여 멸실한 경우, 민법 제202조(점유자의 회복자에 대한 책임)에 따르면 甲이 악의의 점유자로서 부담하는 손해배상범위와 선의이면서 타주점유자로서 부담하는 손해배상범위는 다르지 않다.","w":"악의 점유자와 선의 타주점유자는 모두 손해 전부를 배상한다. 선의 자주점유자만 현존이익의 범위에서 배상한다(민법 제202조).","c":"상"},"변리사2023_60-15-5":{"f":"점유를 침탈당한 甲이 본권인 유치권 소멸에 따른 손해배상청구권을 행사하는 때에는 점유를 침탈당한 날부터 1년 내에 행사해야 하는 것은 아니다.","w":"1년의 제척기간은 점유의 소에 적용된다. 본권 침해를 이유로 한 손해배상청구는 일반 소멸시효에 따른다.","c":"중"},"변리사2024_61-14-3":{"f":"법정대리인의 동의를 받지 않은 미성년자로부터 타인 소유의 자전거를 선의로 매수한 자는 그 미성년자가 제한능력을 이유로 매매계약을 취소하면 선의취득에 기해 그 자전거의 소유권을 취득할 수 없다.","w":"선의취득은 유효한 거래행위를 전제로 한다. 거래행위 자체가 제한능력을 이유로 취소되면 선의취득이 성립하지 않는다.","c":"상"},"변리사2024_61-15-1":{"f":"선의의 점유자라도 본권에 관한 소에 패소한 때에는 그 소가 제기된 때로부터 악의의 점유자로 본다.","w":"본권에 관한 소에 패소하면 소 제기 시부터 악의의 점유자로 본다(민법 제197조 제2항).","c":"상"},"변리사2024_61-15-3":{"f":"직접점유자가 그의 점유를 침탈당하거나 방해당하고 있는 경우, 간접점유자도 점유보호청구권을 행사할 수 있다.","w":"점유보호청구권은 간접점유자도 가진다(민법 제207조).","c":"상"},"변리사2024_61-15-4":{"f":"甲의 점유가 타주점유인 경우, 甲의 특정승계인 乙이 자기의 점유만을 주장하면 그 점유는 자주점유로 추정된다.","w":"점유자는 소유의 의사로 점유하는 것으로 추정되고(제197조 제1항), 승계인이 자기 점유만 주장하면 전 점유자의 하자를 지지 않는다.","c":"상"},"변리사2024_61-15-5":{"f":"과실수취권이 있는 점유자는 점유물로부터 과실을 취득한 경우 회복자에 대하여 점유물을 보존하기 위하여 지출한 통상의 필요비의 상환을 청구할 수 없다.","w":"과실을 취득한 점유자는 통상의 필요비를 청구하지 못한다(민법 제203조 제1항 단서).","c":"상"},"변리사2024_61-17-1":{"f":"공유자는 다른 공유자의 동의없이 자기의 지분을 담보로 제공할 수 있다.","w":"공유자는 자기 지분을 자유롭게 처분할 수 있으므로 담보로 제공하는 것도 다른 공유자의 동의가 필요 없다(민법 제263조).","c":"상"},"변리사2024_61-17-2":{"f":"공유물의 변경은 공유자 전원의 동의로 결정한다.","w":"공유물의 처분·변경에는 전원의 동의가 필요하다(민법 제264조). 지분 과반수로 결정하는 것은 관리행위이다.","c":"상"},"변리사2024_61-17-3":{"f":"공유물의 관리에 관한 사항은 공유자의 지분의 과반수로써 결정한다.","w":"관리는 공유자의 머릿수가 아니라 지분의 과반수로 결정한다(민법 제265조).","c":"상"},"변리사2024_61-17-5":{"f":"총유물에 대한 보존행위는 달리 정함이 없는 한 비법인사단의 사원총회의 결의에 따라야 하고, 각 사원이 단독으로 할 수 없다.","w":"총유물의 보존행위도 사원총회의 결의를 거쳐야 하며 각 사원은 단독으로 할 수 없다(민법 제276조 제1항, 대법원 2005.9.15. 전원합의체 판결).","c":"상"},"변리사2026_63-18-3":{"f":"악의 점유자는 수취한 과실을 반환함에 있어서 그 받은 이익에 이자를 붙여 반환하여야 한다.","w":"악의의 점유자는 받은 이익에 이자를 붙여 반환하고, 손해가 있으면 배상한다(민법 제201조 제2항, 제748조 제2항).","c":"상"},"변리사2026_63-19-1":{"f":"부동산에 대한 점유취득시효가 완성된 경우, 소유명의자는 점유자가 시효가 완성되기까지 그 부동산으로부터 얻은 이익에 대하여 부당이득반환청구를 할 수 없다.","w":"시효취득이 이루어지면 점유자는 소유권을 원시취득하므로, 소유명의자에 대한 부당이득반환 의무가 없다.","c":"중"},"변리사2026_63-19-2":{"f":"토지에 관하여 점유취득시효 완성에 따라 소유권이전등기가 마쳐진 경우, 제3자가 등기명의자의 취득시효 기간 중 일부 기간 동안 해당 토지 일부에 관하여 직접적·현실적인 점유를 한 사실이 있더라도 그 등기가 원인무효의 등기가 되는 것은 아니다.","w":"점유의 계속은 추정되므로, 일부 기간 제3자가 점유한 사실만으로 시효취득이 부정되지 않는다.","c":"중"},"변리사2026_63-19-3":{"f":"취득시효완성 사실을 알면서 소유자로부터 그 부동산을 매수하여 소유권이전등기를 마친 자는 소유자의 등기의무를 승계하지 않는다.","w":"매수인이 취득시효 완성 사실을 알았다는 것만으로 등기의무를 승계하지는 않는다. 시효완성자는 소유자에 대한 이전등기청구권이 있고 제3자에게는 직접 청구하지 못한다.","c":"중"},"변리사2026_63-19-4":{"f":"취득시효기간의 완성 전에 소유자의 채권자에 의하여 시효취득 목적물이 압류 또는 가압류가 된 경우에도 취득시효는 중단되지 않는다.","w":"압류·가압류는 소유자의 재산에 대한 처분 제한일 뿐이며 점유자의 점유를 방해하지 않으므로 취득시효의 중단사유가 되지 않는다.","c":"상"},"변리사2016_53-18-1":{"f":"","w":"사례의 사실관계를 알 수 없어 정확한 결론을 확인할 수 없다. 관습법상 법정지상권은 토지와 건물 소유자가 같았다가 매매 등으로 소유자가 달라지는 경우에만 생긴다.","c":"하"},"변리사2016_53-18-2":{"f":"C가 무허가건물인 경우에도 C의 소유자는 그 건물의 소유를 위한 관습법상 법정지상권을 취득할 수 있다.","w":"무허가건물이어도 관습법상 법정지상권 성립에는 지장이 없다(대법원 판례).","c":"중"},"변리사2016_53-18-4":{"f":"만일 乙이 근저당권 설정 당시 존재하던 B건물을 철거하고 D건물을 신축한 후에 A토지에 대한 저당권이 실행되었다면, B건물과 D건물의 동일성이 인정되지 않더라도 乙은 D건물을 위한 법정지상권을 취득할 수 있다.","w":"저당권 설정 당시 건물이 있었다면 철거 후 신축한 건물에도 법정지상권이 인정될 수 있으며 건물의 동일성은 요구되지 않는다.","c":"중"},"변리사2017_54-15-4":{"f":"지상권을 가진 건물소유자가 그 건물에 전세권을 설정하였으나 그가 2년 이상의 지료를 지급하지 아니한 경우, 토지소유자는 전세권자의 동의 없이 지상권 소멸 청구를 할 수 있다.","w":"토지소유자의 지상권 소멸청구에 전세권자의 동의는 필요 없고, 전세권자에게 통지한 뒤 상당한 기간이 지나야 효력이 생긴다(민법 제288조).","c":"중"},"변리사2017_54-21-1":{"f":"지역권은 다른 약정이 없는 한 요역지소유권에 부종하여 이전한다.","w":"지역권은 요역지 소유권에 부종하여 이전하고, 승역지 소유권에 부종하는 것이 아니다(민법 제292조 제1항).","c":"상"},"변리사2017_54-21-3":{"f":"통행지역권을 시효취득하기 위해서는 요역지의 소유자가 타인의 토지를 20년간 통행하였다는 사실만으로 부족하고, 요역지의 소유자가 타인의 소유인 승역지 위에 통로를 개설하여야 한다.","w":"계속되고 표현된 지역권만 시효취득하므로, 통행지역권은 요역지 소유자가 통로를 개설하여 사용한 경우에 시효취득할 수 있다(민법 제294조).","c":"상"},"변리사2017_54-21-4":{"f":"요역지의 공유자 중 1인이 지역권을 시효로 취득하면 다른 공유자도 지역권을 취득한다.","w":"요역지 공유자 1인이 시효취득하면 다른 공유자도 취득한다(민법 제295조 제1항).","c":"상"},"변리사2017_54-21-5":{"f":"승역지는 반드시 1필의 토지일 필요가 없으며, 토지의 일부 위에도 지역권을 설정할 수 있다.","w":"지역권은 승역지의 일부에도 설정할 수 있다. 요역지는 1필의 토지여야 한다.","c":"상"},"변리사2018_55-16-4":{"f":"지상건물이 없는 토지에 관하여 1번 저당권을 설정할 당시 저당권자가 그 토지에 건물을 축조하는 것에 동의하였더라도 법정지상권은 성립하지 않는다.","w":"법정지상권(민법 제366조)은 저당권 설정 당시 토지 위에 건물이 있어야 성립한다. 저당권자가 건축에 동의했다는 사정만으로는 성립하지 않는다(대법원 1995.12.22. 선고 판결).","c":"상"},"변리사2018_55-21-3":{"f":"지역권자 甲이 그 소유 토지를 乙에게 매도하고 이전등기한 경우, 특별한 사정이 없는 한 乙은 지역권의 이전등기 없이도 지역권을 취득한다.","w":"지역권은 요역지 소유권에 부종하여 이전하므로 요역지 소유권 이전등기만으로 지역권이 함께 이전되고 별도 이전등기가 필요 없다(민법 제292조 제1항).","c":"상"},"변리사2019_56-16-1":{"f":"지상권은 1필 토지의 일부에 대해서도 성립할 수 있다.","w":"지상권은 1필 토지의 일부에도 설정할 수 있다.","c":"중"},"변리사2019_56-16-2":{"f":"지상권자는 존속기간이 만료한 때에 지상물이 현존하는 경우, 지상권설정자에 대해 먼저 지상권의 갱신을 청구할 수 있고, 설정자가 갱신을 원하지 않으면 지상물의 매수를 청구할 수 있다.","w":"갱신청구와 매수청구는 선택적이 아니라 순차적이다. 갱신청구를 거절당한 뒤에 매수를 청구한다(민법 제283조).","c":"상"},"변리사2019_56-16-3":{"f":"지상권은 지상물의 소유를 목적으로 토지를 사용하는 권리이지만, 지상권자는 지상권을 유보한 채 지상물 소유권만을 양도할 수 있다.","w":"지상권과 지상물 소유권은 별개여서 지상권을 유보하고 지상물만 양도할 수 있다. 이 경우 지상물 양수인은 토지를 쓸 근거가 없어 문제가 생길 수 있다.","c":"중"},"변리사2019_56-16-5":{"f":"금융기관이 토지에 저당권과 함께 지료 없는 지상권을 설정받으면서 채무자의 사용수익권을 배제하지 않은 경우, 금융기관은 그 토지의 무단점유자에 대해 지상권침해를 근거로 임료 상당의 손해배상을 청구할 수 없다.","w":"담보 목적의 지상권이고 토지의 사용수익권을 설정자에게 남겨 두었다면, 지상권자는 임료 상당의 손해가 없으므로 배상을 청구할 수 없다(대법원 2018.3.22. 전원합의체 판결).","c":"상"},"변리사2021_58-18-1":{"f":"2020. 10. 1. 당시 丙은 X토지에 대하여 법정지상권 등기를 하지 않았더라도, 丙은 X토지에 대한 법정지상권을 취득한다.","w":"법정지상권은 등기 없이도 법률 규정에 의해 취득한다(민법 제187조). 다만 처분하려면 등기를 해야 한다.","c":"중"},"변리사2021_58-18-2":{"f":"2020. 10. 1. 丙이 법정지상권을 취득하였더라도 지료를 지급하여야 한다.","w":"법정지상권도 유상이며 지료는 당사자 협의나 법원 결정으로 정한다(민법 제366조). 본인 의사와 무관하게 취득했다는 이유로 지료가 면제되지 않는다.","c":"상"},"변리사2021_58-18-4":{"f":"2021. 2. 10. 戊는 법정지상권 등기를 하여야 X토지에 대하여 법정지상권을 취득한다.","w":"지상권을 건물과 함께 양수하는 것은 법률행위에 의한 물권변동이므로 이전등기를 해야 취득한다(민법 제186조).","c":"중"},"변리사2021_58-20-4":{"f":"전세권에 저당권을 설정한 경우, 전세기간이 만료되면 전세권의 저당권자는 전세권 자체에 대하여 저당권을 실행할 수 없고 전세금반환채권에 대한 물상대위권을 행사하여야 한다.","w":"전세기간이 끝나면 전세권의 용익물권적 권능이 소멸하므로 전세권 자체를 경매할 수 없다. 전세금반환채권을 압류하는 물상대위로 변제받는다.","c":"상"},"변리사2023_60-19-1":{"f":"甲이 보증금의 반환을 담보하기 위하여 전세권을 설정하면서 이와 동시에 목적물을 인도하지 않았더라도 전세권의 설정은 효력이 있다.","w":"전세권 성립에는 목적물의 인도가 필요하지 않고 전세권설정등기만으로 성립한다.","c":"상"},"변리사2023_60-19-2":{"f":"전세금의 지급은 전세권 성립의 요소가 되지만 전세금을 현실적으로 지급하지 않고 기존의 채권으로 대신할 수 있다.","w":"전세금은 반드시 현실로 수수될 필요가 없고 기존 채권으로 갈음할 수 있다.","c":"상"},"변리사2023_60-19-4":{"f":"임대차보증금의 반환을 담보하기 위하여 전세권설정등기가 경료되었음을 丙이 알지 못한 경우에는 甲은 연체차임의 공제를 가지고 丙에게 대항할 수 없다.","w":"전세권이 임대차보증금 담보 목적으로 설정되었다는 사정을 선의로 알지 못한 제3자에게는 연체차임 공제를 주장할 수 없다.","c":"중"},"변리사2023_60-19-5":{"f":"전세권의 존속기간이 만료되면 丙은 X상가에 대한 전세권저당권을 실행하는 방법이 아니라 전세금반환채권에 대한 물상대위의 방법으로 乙에 대한 대여금채권을 회수하여야 한다.","w":"전세권 존속기간이 끝나면 전세권저당권자는 전세권 자체를 경매할 수 없고 전세금반환채권에 물상대위권을 행사한다.","c":"상"},"변리사2024_61-19-1":{"f":"甲이 丙에게 Y건물을 인도하지 않은 경우에도, 특별한 사정이 없는 한 丙의 전세권은 성립한다.","w":"전세권은 등기로 성립하며 목적물의 인도가 성립요건이 아니다.","c":"상"},"변리사2024_61-19-2":{"f":"甲과 丙이 전세권의 존속기간을 약정하지 아니한 경우, 甲과 丙은 언제든지 상대방에 대하여 전세권의 소멸을 통고할 수 있고 상대방이 이 통고를 받은 날부터 6개월이 지나면 전세권은 소멸한다.","w":"존속기간 약정이 없을 때에는 통고 후 6개월이 지나야 소멸하며, 통고를 받은 때 곧바로 소멸하지 않는다(민법 제313조).","c":"상"},"변리사2024_61-19-3":{"f":"전세금 3억 원은 현실적으로 수수되지 않아도 되며, 丙이 甲에 대하여 갖는 기존의 채권으로 전세금의 지급에 갈음할 수 있다.","w":"전세금은 기존 채권으로 갈음할 수 있다.","c":"상"},"변리사2024_61-19-4":{"f":"특별한 사정이 없는 한, 전세기간 중 丙은 甲의 동의를 얻지 않고도 Y건물을 타인에게 임대할 수 있다.","w":"전세권자는 설정자의 동의 없이 전전세·임대를 할 수 있다(민법 제306조 본문). 설정행위로 금지한 경우에만 제한된다.","c":"상"},"변리사2026_63-20-5":{"f":"지상물매수청구에 따른 지상물매매가격의 산출은 지상권 소멸 당시의 시가가 아니라 지상물 매수청구 당시의 시가에 의한다.","w":"매수청구권은 형성권이므로 행사한 때 매매계약이 성립하고, 가격은 매수청구 당시의 시가이다.","c":"중"},"변리사2026_63-21-4":{"f":"전세권설정자는 전세권자에 대하여 전세권자에게 책임있는 사유로 인하여 전세목적물이 멸실됨에 따른 손해배상채권 이외의 다른 채권을 가지고 전세금반환채권에 대하여 물상대위권을 행사한 전세권저당권자에게 상계 등으로 대항할 수 없다.","w":"저당권자가 물상대위로 전세금반환채권을 압류한 경우에는 민법 제315조의 손해배상채권 이외의 채권으로 상계하여 대항할 수 없다.","c":"상"},"변리사2016_53-20-2":{"f":"甲이 공장을 점유하는 과정에서 폭력을 사용하는 등의 불법행위가 있었다면 공장을 점유하였더라도 유치권은 성립하지 않는다.","w":"점유가 불법행위로 시작된 경우에는 유치권이 성립하지 않는다(민법 제320조 제2항).","c":"상"},"변리사2016_53-20-3":{"f":"丙 은행에 근저당권이 설정된 후에 공장을 점유한 甲도 매수인 丁에 대해서는 유치권을 주장할 수 있다.","w":"저당권 설정 뒤에 유치권을 취득해도 경매개시 결정 기입등기 전에 점유를 취득했다면 매수인에게 대항할 수 있다(대법원 2009.1.15. 선고 판결).","c":"중"},"변리사2016_53-20-4":{"f":"甲이 丁에게 유치권을 행사할 수 있다는 것은 丁에게 직접 공사잔금 5억원을 청구할 수 있음을 뜻하지 않는다.","w":"유치권은 변제를 받을 때까지 유치물의 인도를 거절하는 권리이다. 매수인에게 채무자의 채무를 직접 청구할 수 있다는 뜻은 아니다.","c":"상"},"변리사2016_53-21-2":{"f":"丙이 질권설정 사실을 승낙한 후 그 질권설정계약이 합의해지된 경우, 甲이 해지를 이유로 丙에게 원래의 채권으로 대항하려면 질권자 乙이 丙에게 해지 사실을 통지하여야 한다.","w":"질권설정계약이 합의해지된 경우 질권자가 제3채무자에게 해지 사실을 통지해야 질권설정자가 원래의 채권으로 대항할 수 있다.","c":"중"},"변리사2016_53-21-4":{"f":"甲에게 이미 변제한 丙이 착오로 乙에게 이의를 보류하지 아니하고 승낙하였더라도, 乙에게 중과실이 있다면 丙은 변제로 乙에게 대항할 수 있다.","w":"이의를 보류하지 않은 승낙으로 항변을 잃는 것은 질권자가 선의·무과실일 때이다. 질권자에게 중과실이 있으면 대항할 수 있다(민법 제451조 제1항).","c":"중"},"변리사2016_53-21-5":{"f":"乙이 丙에게 직접청구권을 행사하여 변제받은 경우, 입질채권의 발생원인인 계약관계가 무효였다면 丙은 乙을 상대로 부당이득반환을 청구할 수 없다.","w":"제3채무자가 질권자에게 한 변제는 질권설정자에게 한 변제로 취급되므로, 제3채무자는 질권자가 아니라 질권설정자에게 부당이득반환을 청구해야 한다.","c":"중"},"변리사2016_53-22-4":{"f":"근저당권설정등기가 원인 없이 말소된 이후에, 근저당목적물인 부동산에 관하여 다른 근저당권자의 신청에 따라 경매절차가 진행되어 매각허가결정이 확정되고 매수인이 매각대금을 완납한 경우, 그 근저당권은 소멸한다.","w":"경매에서 매수인이 대금을 납부하면 부동산 위의 저당권은 소멸하고, 등기가 원인 없이 말소되었더라도 마찬가지이다.","c":"중"},"변리사2017_54-19-5":{"f":"저당권의 효력은 저당부동산에 대한 압류가 있은 후에 저당권설정자가 그 부동산으로부터 수취한 과실 또는 수취할 수 있는 과실에 미친다.","w":"저당권은 압류 이후의 과실에만 미친다(민법 제359조).","c":"상"},"변리사2017_54-20-1":{"f":"경매개시결정이 있은 후, 甲이 경매신청을 취하하더라도 채무확정의 효과는 번복되지 않는다.","w":"경매신청 시에 확정된 피담보채권은 그 뒤 경매신청을 취하해도 번복되지 않는다(대법원 판례).","c":"상"},"변리사2017_54-22-4":{"f":"양도담보권자는 사용수익할 수 있는 정당한 권한이 있는 채무자나 그 채무자로부터 사용수익할 수 있는 권한을 승계한 자에 대하여 그 사용수익을 하지 못한 것을 이유로 임료 상당의 손해배상이나 부당이득반환을 청구할 수 없다.","w":"담보 목적의 양도에서는 설정자가 사용수익권을 가지므로, 담보권자는 설정자에게 임료 상당 손해배상이나 부당이득반환을 청구할 수 없다.","c":"상"},"변리사2017_54-24-3":{"f":"유치권에 의한 경매절차가 정지된 상태에서 그 목적물에 대한 담보권실행을 위한 경매가 진행되어 매각이 이루어지더라도 그 유치권은 소멸하지 않는다.","w":"유치권에 의한 경매는 인수주의이므로, 유치권은 담보권 실행 경매의 매수인이 인수한다.","c":"중"},"변리사2018_55-23-1":{"f":"세금체납을 이유로 한 체납처분압류가 되어 있는 부동산에 대한 경매절차가 개시되기 전에 유치권을 취득한 유치권자는 그 경매절차의 매수인에게 유치권을 주장할 수 있다.","w":"체납처분압류는 경매절차가 개시된 압류와 다르므로, 압류 이후 유치권을 취득했더라도 경매절차 전에 취득했다면 대항할 수 있다(대법원 2014.3.20. 전원합의체 판결).","c":"중"},"변리사2018_55-23-3":{"f":"매도인이 중도금만 받고서 매수인에게 부동산의 소유권을 이전한 경우, 매도인은 잔금채권을 피담보채권으로 하여 매수인에 대하여 유치권을 행사할 수 없다.","w":"소유권을 이전하여 점유가 매수인에게 넘어간 후에는 유치권이 성립하지 않고, 잔금채권은 목적물에 관하여 생긴 채권으로 보기 어렵다.","c":"중"},"변리사2018_55-23-4":{"f":"부동산 근저당권에 기한 압류의 효력이 발생한 후에 취득한 유치권으로는 그 근저당권에 기한 경매절차의 매수인에게 대항할 수 없다.","w":"압류 이후에 점유를 취득한 유치권은 처분금지 효력에 반하여 매수인에게 대항할 수 없다(대법원 2009.1.15. 선고 판결).","c":"상"},"변리사2018_55-23-5":{"f":"건물신축공사를 도급받은 수급인이 사회통념상 독립한 건물이 되지 못한 정착물을 토지에 설치한 상태에서 공사가 중단된 경우, 토지에 대하여 유치권을 행사할 수 없다.","w":"정착물이 독립한 건물이 아니면 토지에 부합하고, 공사대금채권이 토지에 관하여 생긴 채권이 아니므로 유치권이 성립하지 않는다.","c":"중"},"변리사2019_56-18-2":{"f":"질권설정을 위한 인도는 현실의 인도뿐 아니라 점유개정에 의하여서는 안 된다.","w":"동산질권은 점유개정으로 설정할 수 없다(민법 제332조).","c":"상"},"변리사2019_56-19-2":{"f":"유치권자는 채권의 변제를 받기 위하여 유치물을 경매할 수 있지만 매각대금에서 후순위 권리자보다 우선변제를 받을 수는 없다.","w":"유치권은 우선변제권이 없고 인도거절권만 있다.","c":"상"},"변리사2019_56-19-3":{"f":"수급인이 자신의 노력과 재료를 들여 신축한 건물에 대한 소유권을 원시취득한 경우, 수급인은 공사대금을 지급받을 때까지 유치권을 행사할 수 없다.","w":"유치권은 타인의 물건에 대해서만 성립하므로 수급인 자기 소유의 건물에는 성립하지 않는다.","c":"상"},"변리사2019_56-19-4":{"f":"유치권의 피담보채권의 소멸시효기간이 확정판결 등에 의하여 10년으로 연장된 경우, 유치권이 성립된 부동산의 매수인은 종전의 단기소멸시효를 원용할 수 없다.","w":"시효기간 연장은 채권자·채무자 사이에서 생긴 것이어서 매수인은 연장 전의 단기시효를 원용하지 못한다.","c":"중"},"변리사2019_56-19-5":{"f":"공사대금채권에 기하여 유치권을 행사하는 자가 스스로 보존에 필요한 범위 내에서 유치물인 주택에 거주하며 사용하는 경우에는 소유자가 유치권의 소멸을 청구할 수 없다.","w":"보존에 필요한 사용은 소유자의 승낙 없이도 할 수 있다(민법 제324조 제2항 단서).","c":"상"},"변리사2019_56-21-4":{"f":"","w":"사안을 특정할 수 없어 구체적 우선변제 범위를 확인할 수 없다. 확정일자만으로는 부족하고 대항력(인도와 주민등록)을 갖춰야 우선변제권이 생기며, 변제 범위는 선순위 권리와의 순위에 따라 정해진다.","c":"하"},"변리사2019_56-21-5":{"f":"丙이 적법하게 배당요구를 하였다면 배당받을 수 있었던 금액이 丙의 적법한 배당요구가 없어서 丁과 戊에게 배당된 경우, 丙은 丁과 戊에게 부당이득반환을 청구할 수 없다.","w":"적법하게 배당요구를 하지 않은 사람은 배당받을 지위에 있지 않으므로, 배당받은 다른 채권자를 상대로 부당이득반환을 청구할 수 없다(대법원 판례).","c":"중"},"변리사2019_56-22-2":{"f":"甲이 담보권실행을 통하여 우선변제 받게 되는 이자나 지연배상금 등 피담보채권의 범위는 담보권 실행 통지 당시를 기준으로 확정된다.","w":"청산금 평가를 위한 피담보채권액은 담보권 실행 통지 당시를 기준으로 확정한다(가등기담보 등에 관한 법률 제3조 제1항).","c":"중"},"변리사2019_56-22-3":{"f":"甲이 담보권실행을 통지하고 2개월의 청산기간이 지난 경우, 청산금의 지급이 없다면 乙은 대여금을 변제하고 가등기말소를 청구할 수 있다.","w":"채무자는 청산금 지급 전까지 채무를 변제하고 가등기 말소를 청구할 수 있다(가등기담보 등에 관한 법률 제11조).","c":"중"},"변리사2019_56-22-4":{"f":"甲이 주관적으로 평가한 청산금의 액수가 정당하게 평가된 청산금의 액수에 미치지 못하더라도 담보권실행 통지의 효력은 인정된다.","w":"통지한 청산금이 정당한 평가액에 미달해도 통지는 유효하며, 채권자는 정당한 청산금을 지급해야 소유권을 취득한다(대법원 판례).","c":"중"},"변리사2019_56-22-5":{"f":"甲이 담보권실행을 위해 통지하여야 할 청산금의 평가액은 통지 당시의 목적부동산 가액에서 그 당시의 목적부동산에 존재하는 선순위 담보로 인한 채권액을 공제한 차액이다.","w":"공제하는 채권액은 선순위 담보권에 의해 담보된 채권액이며, 모든 피담보채권액이 아니다(가등기담보 등에 관한 법률 제3조 제1항).","c":"중"},"변리사2019_56-24-1":{"f":"질권의 목적인 채권의 양도행위에는 질권자의 동의가 필요하지 않다.","w":"질권설정자가 입질채권을 양도하는 것은 질권의 소멸·변경이 아니므로 질권자의 동의가 필요하지 않다. 질권자의 동의가 필요한 것은 질권의 목적권리를 소멸·변경하는 행위이다(민법 제352조).","c":"중"},"변리사2021_58-19-3":{"f":"저당권부 채권을 양수한 채권자가 채권양도의 대항요건을 갖추지 않았더라도 그보다 후순위 저당권자에 대하여 채권양도로써 대항할 수 있다.","w":"후순위 저당권자는 채권양도의 대항요건 흠결을 주장할 정당한 이익이 있는 제3자가 아니다(대법원 판례).","c":"중"},"변리사2021_58-21-2":{"f":"유치권자가 유치물의 보존에 필요한 사용을 한 경우에도 특별한 사정이 없는 한, 차임 상당의 이득을 소유자에게 반환할 의무가 있다.","w":"보존에 필요한 사용은 허용되지만 그로 인한 이익은 부당이득으로 소유자에게 반환해야 한다(대법원 2009.9.24. 선고 판결).","c":"중"},"변리사2021_58-21-3":{"f":"건물공사대금의 채권자가 그 건물에 대하여 유치권을 행사하는 동안에도 그 공사대금채권의 소멸시효는 진행한다.","w":"유치권을 행사하더라도 피담보채권의 소멸시효는 진행한다(민법 제326조).","c":"상"},"변리사2021_58-21-4":{"f":"임대인과 임차인 사이에 임대차 종료에 따른 건물명도 시에 권리금을 반환하기로 약정한 경우, 임차인은 권리금반환청구권을 가지고 건물에 대한 유치권을 행사할 수 없다.","w":"권리금반환청구권은 건물에 관하여 생긴 채권이 아니므로 유치권의 피담보채권이 될 수 없다(대법원 1994.10.14. 선고 판결).","c":"상"},"변리사2021_58-21-5":{"f":"유치권자가 경매개시결정등기 전에 부동산에 관하여 유치권을 취득하였다면, 그 취득에 앞서 저당권설정등기가 먼저 되어 있었더라도 경매절차의 매수인에게 자기의 유치권으로 대항할 수 있다.","w":"저당권 설정 후 취득한 유치권이라도 경매개시결정 기입등기 이전에 점유를 취득했다면 매수인에게 대항할 수 있다(대법원 2009.1.15. 선고 판결).","c":"상"},"변리사2021_58-23-5":{"f":"저당권부 채권에 질권을 설정하면서 그 저당권의 피담보채권만을 질권의 목적으로 하고 저당권은 질권의 목적으로 하지 않는 것도 허용된다.","w":"피담보채권만을 질권의 목적으로 할 수 있고, 이는 저당권의 부종성에 반하지 않는다.","c":"중"},"변리사2023_60-20-1":{"f":"채무자는 상당한 담보를 제공하고 유치권의 소멸을 청구할 수 있는데, 유치물 가액이 피담보채권액보다 적을 경우에는 유치물 가액에 해당하는 담보를 제공하면 된다.","w":"유치권 소멸청구의 담보는 유치물의 가액을 기준으로 한다(민법 제327조).","c":"중"},"변리사2023_60-20-2":{"f":"유치권자가 유치물에 대한 점유를 빼앗긴 경우에는 점유를 회복하기 전에는 유치권이 인정되지 않는다.","w":"유치권은 점유를 상실하면 소멸하고(민법 제328조), 점유회수의 소로 점유를 되찾아야 유치권이 되살아난다.","c":"중"},"변리사2023_60-20-3":{"f":"유치권의 존속 중에 유치물의 소유권이 제3자에게 양도된 경우에도 유치권자는 그 제3자에 대하여 유치권을 행사할 수 있다.","w":"유치권은 물권이므로 누구에게나 주장할 수 있다. 소유자가 바뀌어도 유치권자는 새 소유자에게 유치권을 행사한다.","c":"상"},"변리사2023_60-20-5":{"f":"수급인은 도급계약에 따라 자신의 재료와 노력으로 건축된 자기 소유의 건물에 대해서는 도급인으로부터 공사대금을 지급받을 때까지 유치권을 가지지 못한다.","w":"유치권은 타인의 물건에 대하여 성립하므로 수급인 자신이 소유권을 원시취득한 건물에는 유치권이 성립하지 않는다.","c":"상"},"변리사2023_60-22-1":{"f":"경매절차의 매수인이 증축부분의 소유권을 취득하기 위해서는 부합된 증축부분이 기존건물에 대한 경매절차에서 경매목적물로 평가되었을 것을 요하지 않는다.","w":"저당권의 효력은 부합물에 미치므로, 증축부분이 경매목적물로 평가되지 않았더라도 매수인이 소유권을 취득한다(대법원 판례).","c":"상"},"변리사2023_60-23-2":{"f":"공동근저당권자가 X건물과 Y건물에 대하여 공동저당을 설정한 후, 제3자가 신청한 X건물에 대한 경매절차에 참가하여 배당을 받더라도 Y건물에 대한 피담보채권은 확정되지 않는다.","w":"공동근저당권자 자신이 경매를 신청한 경우와 달리, 타인이 신청한 경매에서 배당받은 것만으로 다른 부동산의 피담보채권이 확정되지는 않는다.","c":"중"},"변리사2023_60-24-1":{"f":"가등기담보권자가 목적물의 소유권을 취득하려면 청산금 통지 당시 목적물의 평가액과 피담보채권액의 범위를 밝혀야 한다.","w":"평가액과 채권액은 담보권 실행 통지 당시를 기준으로 밝히며, 담보설정 당시가 기준이 아니다(가등기담보 등에 관한 법률 제3조).","c":"중"},"변리사2023_60-24-3":{"f":"목적부동산의 평가액이 채권액에 미달하여 청산금이 없다고 인정되는 때에도 그 뜻을 채무자에게 통지하여야 한다.","w":"청산금이 없다고 평가되는 때에도 그 뜻을 통지해야 한다(가등기담보 등에 관한 법률 제3조 제1항).","c":"상"},"변리사2023_60-24-4":{"f":"채권자가 담보목적부동산에 관하여 이미 소유권이전등기를 마친 경우에도 청산금을 채무자에게 지급하지 않으면 담보목적부동산의 소유권을 취득하지 못한다.","w":"청산금을 지급하지 않은 채 이전등기를 마쳤다 해도 소유권을 취득하지 못한다(가등기담보 등에 관한 법률 제4조 제2항).","c":"상"},"변리사2023_60-24-5":{"f":"채권자가 평가한 청산금의 액수가 정당하게 평가된 청산금의 액수에 미치지 못하는 경우에도 담보권 실행통지로서의 효력이 있다.","w":"통지한 금액이 정당한 평가액에 미달해도 통지의 효력은 인정되고, 정당한 청산금을 지급해야 소유권을 취득한다(대법원 판례).","c":"중"},"변리사2024_61-20-5":{"f":"유치권자가 소유자의 승낙 없이 유치목적물을 임대한 경우, 임차인의 점유는 소유자에게 대항할 수 있는 적법한 권원에 기한 것이 아니다.","w":"유치권자는 소유자의 승낙 없이 유치물을 임대할 수 없고, 임대하면 소유자가 유치권의 소멸을 청구할 수 있다(민법 제324조 제2항, 제3항).","c":"상"},"변리사2024_61-21-4":{"f":"채무의 이행기가 도래하더라도 물상보증인은 채무자에게 미리 구상권을 행사할 수 없다.","w":"수탁보증인과 달리 물상보증인에게는 사전구상권이 인정되지 않는다.","c":"중"},"변리사2024_61-22-2":{"f":"저당권 등기가 위법하게 말소된 후 그 저당부동산이 경매절차에서 매각된 경우, 저당권자는 매수인을 상대로 말소된 저당권 등기의 회복을 청구할 수 없다.","w":"경매에서 매각되면 저당권은 소멸하므로 매수인에게 회복등기를 청구할 수 없다.","c":"중"},"변리사2024_61-24-2":{"f":"가등기담보권이 설정되기 위해서 피담보채권이 등기되어야 하는 것은 아니다.","w":"가등기담보에서는 가등기가 등기되어야 하고, 피담보채권 자체가 등기사항은 아니다.","c":"중"},"변리사2026_63-16-1":{"f":"매매대금 채무를 담보하기 위하여 가등기를 한 경우에는 「가등기담보 등에 관한 법률」이 적용되지 않는다.","w":"이 법은 소비대차나 준소비대차에 기한 채권의 담보에 적용된다. 매매대금 채권 담보에는 적용되지 않는다(가등기담보 등에 관한 법률 제1조).","c":"상"},"변리사2026_63-16-2":{"f":"공동명의로 담보가등기를 마친 수인(數人)의 채권자가 각자의 지분별로 별개의 독립적인 매매예약완결권을 가지는 경우, 채권자 중 1인은 단독으로 자신의 지분에 관하여 소유권이전의 본등기절차 이행청구를 할 수 있다.","w":"각자가 독립적인 예약완결권을 가진다면 각 채권자는 자기 지분에 관하여 단독으로 본등기를 청구할 수 있다.","c":"중"},"변리사2026_63-16-4":{"f":"채권자가 평가한 청산금의 액수가 정당하게 평가된 청산금의 액수에 미치지 못하는 경우에도 담보권 실행통지로서의 효력이 있다.","w":"통지한 금액이 정당한 평가액에 미달해도 통지는 유효하고, 채권자는 정당한 청산금을 지급해야 소유권을 취득한다.","c":"중"},"변리사2026_63-16-5":{"f":"채무담보를 위하여 가등기가 경료되어 있는 경우, 특별한 사정이 없는 한 피담보채무의 변제가 가등기말소절차의 이행보다 먼저 이행되어야 하고 둘은 동시이행관계에 있지 않다.","w":"채무자의 변제가 선이행이며, 변제와 가등기 말소는 동시이행 관계가 아니다.","c":"상"},"변리사2026_63-22-2":{"f":"상가임대인이 임차건물의 객관적 가치상승과 무관하게 임차인이 지출한 비용에 대해서도 임차인에게 상환하기로 약정한 경우, 임차인은 그 채권을 피담보채권으로 하여 유치권을 행사할 수 없다.","w":"건물에 관하여 생긴 채권이 아니라 약정에 따른 채권이어서 유치권의 피담보채권이 될 수 없다.","c":"중"},"변리사2026_63-22-3":{"f":"유치권자가 선관주의의무를 위반하여 유치물을 타인에게 임대한 경우, 그 후 유치물을 양수한 자도 유치권자에 대하여 선관주의의무 위반을 이유로 유치권소멸을 청구할 수 있다.","w":"유치권 소멸청구권은 소유자에게 있고 소유권을 양수한 자도 행사할 수 있다.","c":"중"},"변리사2026_63-22-4":{"f":"甲이 하나의 채권을 피담보채권으로 하여 乙 소유 여러 필지의 토지에 대하여 유치권을 취득하고, 일부 필지의 토지에 대하여 乙의 승낙없이 무단으로 사무실을 설치한 경우, 乙은 甲에게 그 일부 필지에 대한 유치권의 소멸만을 청구할 수 있다.","w":"의무위반이 있는 필지에 한하여 소멸을 청구할 수 있고, 유치목적물 전부에 대한 소멸을 청구할 수는 없다.","c":"중"},"변리사2026_63-22-5":{"f":"저당목적물에 유익비를 지출한 저당목적물의 제3취득자는 저당권실행에 따른 경매절차의 매수인에 대하여 민법 제367조의 제3취득자의 비용상환청구권을 피담보채권으로 하는 유치권을 행사할 수 없다.","w":"제367조의 비용상환청구권은 경매대가에서 우선 상환받는 권리일 뿐, 이를 피담보채권으로 한 유치권을 매수인에게 행사할 수는 없다.","c":"중"},"변리사2026_63-23-1":{"f":"임대차보증금반환채권에 대하여 질권을 설정하는 경우, 그 채권증서인 임대차계약서를 질권자에게 교부하지 않아도 질권의 효력이 생긴다.","w":"임대차계약서는 질권설정을 위해 교부해야 하는 채권증서가 아니다. 질권설정 계약과 통지·승낙으로 효력이 생긴다.","c":"중"},"변리사2016_53-25-2":{"f":"특정물채권에서 채무자의 목적물에 대한 선관주의의무의 존속기간은 특정물채무의 성립시부터 인도할 때까지이다.","w":"선관주의의무는 목적물을 인도할 때까지 계속된다(민법 제374조). 이행기까지가 아니다.","c":"상"},"변리사2016_53-26-4":{"f":"손해발생으로 인하여 피해자에게 이득이 생겼다면 손해액을 산정할 때 먼저 과실상계를 한 후에 손익상계를 하여야 한다.","w":"과실상계를 먼저 하고 그 결과에서 손익상계를 한다(대법원 판례).","c":"상"},"변리사2016_53-27-1":{"f":"임차건물이 화재로 소실된 경우 그 화재의 발생 원인이 불명이면, 임차인은 임차 건물의 보존에 관한 선관주의의무를 다하지 않은 경우 그 책임을 면하지 못한다.","w":"원인 불명의 화재라도 임차인이 자신에게 귀책사유가 없음을 증명하지 못하면 책임을 진다(대법원 판례).","c":"중"},"변리사2016_53-27-2":{"f":"이행보조자의 불법행위로 인하여 채무자가 채무불이행책임을 부담하는 경우 이행보조자의 손해배상책임과 채무자의 채무불이행책임은 부진정연대채무관계에 있다.","w":"두 책임은 발생 근거가 서로 다른 별개 채무여서 부진정연대채무이다.","c":"상"},"변리사2016_53-27-3":{"f":"채무자의 제3채무자에 대한 채권의 가압류가 있는 경우에도 그 채권의 이행기가 도래하였다면 제3채무자는 그 지체책임을 부담한다.","w":"가압류가 있어도 제3채무자는 채무자에게 지급하지 못할 뿐 이행지체책임은 면하지 못한다(대법원 2000.5.26. 선고 판결).","c":"중"},"변리사2016_53-27-4":{"f":"채무불이행으로 인하여 계약이 합의해제 되었더라도 손해배상을 청구하려면 합의해제 시 손해배상 청구권을 유보하는 특약이 필요하다.","w":"합의해제를 하면서 손해배상에 관해 아무 약정이 없으면 채무불이행으로 인한 손해배상을 청구할 수 없다(대법원 판례).","c":"상"},"변리사2016_53-29-4":{"f":"원인채무의 이행확보를 위해 발행한 어음의 반환과 원인채무의 이행이 동시이행관계에 있는 경우에도 원인채무의 이행기가 지나면 채무자는 이행지체책임을 진다.","w":"어음 반환과의 관계는 동시이행 항변 문제이며, 판례의 구체적 결론은 확신하지 못한다.","c":"하"},"변리사2017_54-25-1":{"f":"매매계약 당시 매매목적 토지의 소유권이 매도인에게 속하지 아니함을 알고 있던 매수인도 소유권이전의무의 이행불능에 매도인의 귀책사유가 있다면 채무불이행을 이유로 계약을 해제하고 손해배상을 청구할 수 있다.","w":"타인 권리를 매매한 경우 매수인이 악의여도 채무불이행 요건을 갖추면 해제와 손해배상이 가능하다.","c":"중"},"변리사2017_54-26-3":{"f":"숙박업자가 숙박계약상의 고객보호의무를 다하지 못하여 투숙객이 사망한 경우, 그 투숙객의 근친자는 숙박계약의 당사자가 아니므로 숙박업자의 숙박계약상의 채무불이행을 이유로 위자료를 청구할 수 없다.","w":"근친자는 계약 당사자가 아니므로 채무불이행을 근거로 위자료를 청구할 수 없고 불법행위를 근거로 청구해야 한다.","c":"중"},"변리사2018_55-25-2":{"f":"채권자지체 중에 이행불능이 된 경우, 채권자지체가 발생한 사실에 대한 증명책임은 채무자에게 있다.","w":"채권자지체를 주장하는 쪽, 즉 채무자가 증명해야 한다.","c":"중"},"변리사2018_55-25-3":{"f":"채권자지체로 인하여 채권의 목적물을 보관 또는 변제하기 위한 비용이 증가된 때에 그 증가액은 채권자가 부담한다.","w":"채권자지체로 증가한 보관·변제 비용은 채권자의 부담이다(민법 제403조).","c":"상"},"변리사2018_55-25-4":{"f":"이자 있는 채권의 경우에 채권자지체 중에는 채무자가 이자를 지급할 의무가 없다.","w":"채권자지체 중에는 채무자가 이자를 지급할 필요가 없다(민법 제402조).","c":"상"},"변리사2018_55-25-5":{"f":"민법 제538조 제1항의 ‘채권자의 수령지체 중에 당사자 쌍방의 책임 없는 사유로 채무를 이행할 수 없게 된 때’에 해당하기 위해서는 채무자의 현실 제공 또는 구두 제공이 필요하다.","w":"수령지체가 성립하려면 채무자의 변제 제공이 있어야 하고, 이는 현실 제공 또는 구두 제공이다.","c":"중"},"변리사2019_56-31-3":{"f":"부동산의 소유권이전등기의무자가 그 부동산에 제3자 명의로 가등기를 마쳐주더라도 그것만으로 소유권이전등기의무가 이행불능이 되지는 않는다.","w":"가등기를 마쳐도 소유권은 여전히 의무자에게 있고 본등기 전까지는 이전할 수 있어 이행불능이 아니다.","c":"중"},"변리사2021_58-25-5":{"f":"甲은 乙로부터 1억 원을 빌리면서 5회에 걸쳐 매회 2천만 원씩 분할상환하되, 분할변제기한을 1회라도 지체하였을 때는 기한의 이익을 잃는 것으로 특약한 경우, 특별한 사정이 없는 한 채권자의 청구가 있어야 미상환금액 전부에 대하여 기한이익이 상실되어 지체책임을 진다.","w":"이런 특약은 특별한 사정이 없으면 채권자의 청구 등이 있어야 기한이익이 상실되는 형성권적 특약으로 추정된다.","c":"상"},"변리사2021_58-26-4":{"f":"채권액이 외국통화로 지정된 금액채권인 외화채권의 경우, 채권자는 대용급부권을 행사하여 우리나라 통화로 환산하여 청구할 수 있다.","w":"외화채권은 우리나라 통화로 지급할 수 있는 대용급부권이 있다(민법 제378조).","c":"상"},"변리사2021_58-27-3":{"f":"민법상 임대차에서 목적물을 사용수익하게 할 임대인의 의무는 임대인이 임대차목적물의 소유권을 상실한 것만으로는 이행불능이 되지 않는다.","w":"소유권 상실만으로는 이행불능이 아니고, 임차인이 소유자로부터 반환청구를 받는 등 실제로 사용수익할 수 없게 되어야 이행불능이다.","c":"상"},"변리사2023_60-25-1":{"f":"계약당사자 일방이 자신의 계약상 채무 이행에 장애가 될 수 있는 사유를 계약체결 시에 예견할 수 있었음에도 상대방에게 고지하지 않은 경우, 그 사유로 인해 채무불이행이 되는 것에 대해 귀책사유가 인정될 수 있다.","w":"예견할 수 있었던 장애를 고지하지 않았다면 그것 자체가 귀책사유가 된다.","c":"중"},"변리사2023_60-28-4":{"f":"채무자가 금전채무를 이행하지 않아 발생한 확정된 지연손해금에 대하여 채권자가 이행청구를 하는 경우 그 지연손해금에 대하여 다시 지연손해금의 지급을 구할 수 있다.","w":"확정된 지연손해금은 이행청구를 받은 때부터 다시 지체책임이 생겨 그에 대한 지연손해금을 청구할 수 있다.","c":"상"},"변리사2024_61-25-2":{"f":"특정물매매의 경우, 매수인이 매매대금을 지급하지 않더라도 인도받지 않은 목적물로부터 생긴 과실에 대한 수취권은 특별한 사정이 없는 한 매도인에게 귀속된다.","w":"인도 전 목적물에서 생긴 과실은 매도인의 것이다. 대금을 완납하지 않은 매수인에게 귀속되지 않는다(민법 제587조).","c":"중"},"변리사2024_61-26-2":{"f":"이행기의 정함이 없는 지명채권을 양수한 채권양수인이 채무자를 상대로 그 이행을 구하는 소를 제기하고, 그 소송 계속 중 채무자에 대한 채권양도통지가 이루어진 경우에는 특별한 사정이 없는 한 채무자는 채권양도통지가 도달된 날의 다음 날부터 채권양수인에 대해 이행지체의 책임을 진다.","w":"소 제기 시가 아니라 양도통지가 도달한 다음 날부터 이행지체이다.","c":"상"},"변리사2026_63-26-5":{"f":"토지소유자가 수필의 토지 중 일정 면적을 상대방에게 매도한 경우, 양도할 토지의 위치가 확정되지 않았더라도 특별한 사정이 없는 한 상대방의 채권은 종류채권에 해당하지 않는다.","w":"위치가 정해지지 않았다는 사정만으로 종류채권이 되지는 않는다.","c":"중"},"변리사2026_63-27-4":{"f":"이행불능으로 인한 손해배상청구권은 본래의 채권과 동일성을 가지므로 본래의 채권이 시효로 소멸하면 본래의 채권과 함께 소멸한다.","w":"이행불능으로 인한 손해배상청구권은 본래 채권의 내용이 바뀐 것이어서 본래 채권의 소멸시효 기간이 지나면 함께 소멸한다.","c":"중"},"변리사2016_53-28-4":{"f":"丁의 甲에 대한 채권이 시효완성으로 인하여 소멸하였다면 乙과 丙은 甲의 부담부분 한도에서 채무를 면하게 된다.","w":"연대채무자 1인에 대한 소멸시효 완성은 그 부담부분에 한하여 다른 연대채무자의 이익을 위해서도 효력이 있다(민법 제416조).","c":"중"},"변리사2016_53-30-1":{"f":"丙이 乙에게 자신의 명의로 된 확정일자 있는 채권양도통지서를 발송하여 도달되었더라도, 丙은 乙에게 위 채권양도로 대항할 수 없다.","w":"채권양도의 통지는 양도인이 해야 한다. 양수인이 한 통지는 효력이 없다(민법 제450조 제1항).","c":"상"},"변리사2016_53-30-2":{"f":"매매대금채권에 관하여 甲과 乙 사이에 양도금지 특약이 있더라도, 乙은 경과실로 이를 알지 못한 丙에게 위 특약으로써 대항할 수 없다.","w":"양도금지 특약은 선의의 제3자에게 대항하지 못하고, 중과실이 있어야 악의와 같이 취급한다(민법 제449조 제2항, 대법원 판례).","c":"상"},"변리사2016_53-30-4":{"f":"甲이 乙에 대한 위 채권을 丁에게도 양도하였고 丙과 丁에 대한 양도에 대하여 확정일자 있는 증서에 의한 통지가 이루어졌다면 丙과 丁 간의 우열은 통지가 도달한 일시의 선후에 의한다.","w":"확정일자 있는 통지끼리의 우열은 확정일자의 선후가 아니라 채무자에게 도달한 일시의 선후로 정한다(대법원 1994.4.26. 선고 전원합의체 판결).","c":"상"},"변리사2016_53-30-5":{"f":"丙이 乙에 대하여 매매대금의 지급을 소구(訴求)하였다면 丙이 아직 대항요건을 갖추지 못하였더라도 丙의 재판상 청구는 소멸시효 중단사유로 인정된다.","w":"양수인이 대항요건을 갖추지 못했어도 채권자로서 소를 제기하면 시효중단의 효력이 생긴다.","c":"중"},"변리사2016_53-31-4":{"f":"토지매수인이 그 토지에 관한 임대차보증금 반환채무 등을 인수하면서 채무액을 매매대금에서 공제하기로 약정한 경우, 그 인수는 특별한 사정이 없는 한 이행인수로 보아야 한다.","w":"매매대금에서 공제하기로 한 경우에는 채권자를 면책시키는 것이 아니라 이행인수로 해석한다(대법원 판례).","c":"중"},"변리사2017_54-29-1":{"f":"甲이 1천만원의 채무에 대한 소멸시효 기간이 경과한 후 시효의 이익을 포기한 경우에도, 丙은 소멸시효를 원용하여 연대보증채무의 소멸을 주장할 수 있다.","w":"시효이익 포기는 포기한 사람에게만 효력이 있어 보증인은 별도로 소멸시효를 원용할 수 있다.","c":"상"},"변리사2017_54-29-2":{"f":"甲이 乙에게 8백만원의 채권을 가지고 있는 경우, 丙은 8백만원의 한도 내에서 상계로 채권자에게 대항할 수 있다.","w":"보증인은 주채무자가 채권자에게 가진 채권으로 상계할 수 있는 한도에서 채권자에게 대항할 수 있다(민법 제434조).","c":"중"},"변리사2017_54-29-3":{"f":"乙이 甲에 대한 채권을 丁에게 양도하고 확정일자 있는 증서로 甲에게 통지한 경우, 乙이 丙에게 보증채권 양도의 통지를 하지 않아도 丙에 대한 채권이 丁에게 이전된다.","w":"보증채권은 주채권에 수반하여 이전되므로 보증인에게 따로 통지할 필요가 없다.","c":"상"},"변리사2017_54-29-5":{"f":"甲의 채무가 본래 단기소멸시효에 걸리는 것이었지만 확정판결에 의해 소멸시효 기간이 10년으로 연장된 경우라도, 丙의 보증채무에는 종전의 단기소멸시효기간이 적용된다.","w":"확정판결로 10년으로 연장된 효과는 주채무에만 미치고, 보증채무의 소멸시효 기간은 종전대로이다.","c":"중"},"변리사2017_54-31-1":{"f":"이행인수인은 법정대위를 할 수 있는 변제할 정당한 이익이 있는 자에 해당한다.","w":"이행인수인이 변제할 정당한 이익이 있는 자인지에 관해 판례를 정확히 확신하지 못한다.","c":"하"},"변리사2017_54-31-3":{"f":"부동산 매수인이 매매목적물에 설정된 근저당권의 피담보채무를 이행인수한 뒤 그 변제를 게을리 하여 근저당권이 실행됨으로써 매도인이 매매목적물에 대한 소유권을 상실한 경우, 이는 매수인의 책임 있는 사유로 소유권이전등기의무가 이행불능으로 된 경우에 해당하고 그에 대하여 매도인의 과실은 인정되지 않는다.","w":"이행인수를 한 매수인이 변제를 게을리했으므로 불능의 책임은 매수인에게 있고, 매도인에게는 과실이 없다.","c":"중"},"변리사2017_54-31-4":{"f":"계약당사자로서의 지위가 제3자에게 이전되는 경우, 계약상 지위를 전제로 한 권리관계는 이전되지만 불법행위에 기한 손해배상청구권은 별도의 채권양도절차를 밟아야 제3자에게 이전된다.","w":"계약상 지위 이전이 불법행위에 기한 손해배상청구권까지 당연히 이전시키지는 않는다.","c":"중"},"변리사2017_54-31-5":{"f":"채무자와 인수인의 합의에 의한 중첩적 채무인수의 경우, 채권자의 수익의 의사표시는 계약의 성립요건도 효력발생요건도 아니다.","w":"채권자의 수익의 의사표시는 중첩적 채무인수 계약의 성립요건도 효력발생요건도 아니다(판례).","c":"중"},"변리사2018_55-28-1":{"f":"甲이 丁에 대한 4천만원의 반대채권을 가지고 유효하게 상계한 경우, 丙의 채무도 4천만원이 소멸하여 2천만원의 채무만 남는다.","w":"연대채무자 1인의 상계는 채무자 전원의 이익을 위해 절대적 효력이 있다. 상계된 4천만원 한도에서 모든 채무자의 채무가 소멸한다(민법 제418조 제1항).","c":"중"},"변리사2018_55-29-1":{"f":"丙이 보증계약 후 乙의 변제기를 연장해 준 경우, 특별한 사정이 없는 한 甲은 주채무의 보증계약 당시의 이행기가 되면 乙에게 미리 구상권을 행사할 수 있다.","w":"채권자가 주채무자에게 변제기를 연장해 준 것은 보증인이 주채무자에게 대항할 수 없으므로 보증계약 당시의 이행기가 도래하면 사전구상이 가능하다(민법 제442조 제2항).","c":"중"},"변리사2018_55-29-2":{"f":"甲이 丙에게 변제한 이후 乙과 丙의 계약이 해제되어 소급적으로 소멸한 경우, 甲은 丙을 상대로 이미 이행한 급부를 부당이득으로 반환청구할 수 있다.","w":"해제로 주채무가 소급해서 소멸하므로 보증채무도 없어지고, 보증인이 한 변제는 법률상 원인이 없는 이행이 되어 부당이득으로 반환청구할 수 있다.","c":"중"},"변리사2018_55-29-4":{"f":"丙이 乙에 대한 대금채권을 실행하기 위해 乙의 재산을 압류하면 甲의 보증채무의 소멸시효도 중단된다.","w":"주채무에 대한 시효중단은 보증인에게도 효력이 있다(민법 제440조).","c":"상"},"변리사2018_55-29-5":{"f":"","w":"보증인이 주채무자의 부탁으로 보증한 경우에는 변제한 금액과 이자·비용·손해를 구상할 수 있다. 부탁 없이 보증한 경우에만 주채무자가 이익을 받은 한도에서 구상한다. 사례의 부탁 여부를 알 수 없어 f는 비운다.","c":"하"},"변리사2018_55-30-4":{"f":"채권양도에 대한 乙의 승낙이 있은 후에 채권양도계약이 해제되어 甲이 乙에게 양도철회통지를 한 경우, 乙은 이로써 丙의 채무이행청구에 대하여 대항할 수 없다.","w":"채무자가 양도를 이의 없이 승낙한 뒤에는 양도인이 철회하더라도 선의의 양수인에게 대항할 수 없다.","c":"중"},"변리사2018_55-31-1":{"f":"채무인수인은 특별한 의사표시가 없으면 자신의 구(舊)채무자에 대한 항변사유를 가지고 채권자에게 대항할 수 없다.","w":"인수인 자신이 구채무자에 대해 가진 항변은 채권자에게 대항하는 데 쓸 수 없다. 인수인은 구채무자가 채권자에 대해 갖는 항변으로만 대항한다(민법 제458조).","c":"중"},"변리사2018_55-31-3":{"f":"토지매수인이 토지에 관한 매도인의 채무를 인수하면서 그 채무액을 매매대금에서 공제하기로 약정한 경우, 특별한 사정이 없는 한 이행인수에 해당한다.","w":"대금에서 채무액을 공제하기로 한 약정은 채권자를 면책시키려는 것이 아니므로 이행인수로 본다.","c":"중"},"변리사2018_55-31-4":{"f":"채무자 아닌 제3자가 설정한 근저당권에 관하여 그 제3자의 동의를 얻어 채무인수를 원인으로 채무자를 교체하는 변경등기가 마쳐졌더라도, 특별한 사정이 없는 한 그 근저당권은 그 후 채무인수인이 다른 원인으로 부담하는 채무까지 담보하지는 않는다.","w":"인수한 채무만 담보하고, 이후 별개 원인으로 생긴 채무까지 담보하는 것은 아니다.","c":"상"},"변리사2018_55-31-5":{"f":"","w":"중첩적 채무인수에서 채권자의 수익의 의사표시가 필요한지에 관해 기출 사이에 판례 서술이 엇갈려, 정확한 오답 이유를 확신하지 못한다.","c":"하"},"변리사2019_56-26-4":{"f":"채권자가 연대보증인에게 채무이행을 청구한 경우, 연대보증인은 최고·검색의 항변을 할 수 없다.","w":"연대보증인에게는 최고·검색의 항변권이 없다(민법 제437조 단서).","c":"상"},"변리사2019_56-32-5":{"f":"매수인이 매매목적물에 관한 임대차보증금반환채무를 인수하면서 그 채무액을 매매대금에서 공제하기로 약정한 경우, 임차인의 승낙이 없으면 이행인수로 본다.","w":"병존적 채무인수가 아니라 이행인수로 본다. 임차인의 승낙이 있어야 면책적 인수가 된다.","c":"중"},"변리사2021_58-28-1":{"f":"채무자와 채무인수인 사이의 면책적 채무인수에서 채권자가 승낙을 거절하였다면 다시 승낙하더라도 채무인수의 효력이 생기지 않는다.","w":"채권자가 한 번 거절하면 확정되어 이후의 승낙은 효력이 없다.","c":"상"},"변리사2021_58-28-2":{"f":"채무자와 채무인수인 사이의 면책적 채무인수에서 채권자가 채무인수인에게 인수금의 지급을 청구하는 것은 채무인수의 승낙으로 볼 수 있다.","w":"채권자가 인수인에게 직접 이행을 청구했다면 묵시적 승낙으로 인정될 수 있다.","c":"상"},"변리사2021_58-28-3":{"f":"채무자와 채무인수인 사이의 면책적 채무인수에서 채권자의 승낙이 없는 경우에도, 채무자와 인수인 사이에는 이행인수로서의 효력이 인정될 수 있다.","w":"채권자의 승낙이 없어 면책적 인수가 되지 않더라도 당사자 사이에서는 이행인수로 해석된다.","c":"중"},"변리사2021_58-28-5":{"f":"면책적 채무인수의 경우, 채무인수인은 채무자에 대한 항변사유로 채권자에게 대항할 수 없다.","w":"인수인이 채무자에게 가진 항변은 채권자에게 대항하는 데 쓸 수 없다. 전(前) 채무자가 채권자에 대해 가진 항변만 쓴다(민법 제458조).","c":"중"},"변리사2023_60-31-2":{"f":"저당권이 설정된 부동산의 매수인이 피담보채무를 인수하면서 그 채무액을 매매대금에서 공제하기로 하고 잔액만을 지급한 경우, 특별한 사정이 없는 한 매수인은 잔금 지급의무를 다한 것으로 본다.","w":"채무 인수액을 대금에서 공제하기로 했다면 잔액을 지급하면 대금 지급의무를 다한 것이다.","c":"중"},"변리사2023_60-31-3":{"f":"주택의 임차인이 대항력을 갖추었더라도 그가 그 주택의 소유권을 취득하면 특별한 사정이 없는 한 임대인에 대한 보증금반환청구권은 혼동으로 소멸한다.","w":"임차인이 소유권을 취득해 채권자와 채무자가 같아지면 혼동으로 소멸하는 것이 원칙이다.","c":"하"},"변리사2023_60-31-4":{"f":"중첩적 채무인수에서 채무자와 인수인은 채권자에 대하여 원칙적으로 연대채무 관계에 있다.","w":"중첩적 채무인수는 특별한 사정이 없으면 연대채무이다. 부진정연대로 보는 것은 예외이다.","c":"중"},"변리사2023_60-31-5":{"f":"채무가 인수된 경우 특별한 사정이 없는 한 제3자가 제공한 담보물권은 소멸한다.","w":"제3자가 제공한 담보는 그 제3자의 동의가 없으면 채무인수 때 소멸한다(민법 제459조 단서).","c":"상"},"변리사2024_61-30-1":{"f":"부동산매매로 인한 소유권이전등기청구권이 양도된 경우, 양도인의 채무자에 대한 통지만으로는 채무자에 대한 대항력이 발생하지 않고 채무자의 동의나 승낙이 있어야 한다.","w":"부동산 이전등기청구권 양도는 채무자의 동의나 승낙이 있어야 채무자에게 대항할 수 있다(대법원 판례).","c":"상"},"변리사2024_61-30-2":{"f":"소송행위를 하게 하는 것을 주목적으로 지명채권의 양도가 이루어진 경우, 그 채권양도가 신탁법상의 신탁에 해당하지 않는 경우에도 무효이다.","w":"소송신탁은 신탁법 제6조에 따라 무효이고, 신탁에 해당하지 않아도 민법 제103조 위반으로 무효이다.","c":"상"},"변리사2024_61-30-3":{"f":"주채무자에 대한 지명채권이 양도된 후 양수인이 보증인에게 보증채권을 행사하기 위해서는 주채권의 양도에 대한 대항요건과 별도로 보증채권의 양도에 대한 대항요건을 갖출 필요가 없다.","w":"보증채권은 주채권에 수반하여 함께 이전하므로 주채권 양도의 대항요건으로 족하다.","c":"상"},"변리사2024_61-30-5":{"f":"채권자와 양수인 사이의 계약에 의해 지명채권이 양도된 경우, 양수인은 제3자에 대한 대항요건을 구비하기 위하여 채권자에게 채권양도통지절차의 이행을 청구할 수 있다.","w":"양수인은 양도인에게 통지의 이행을 청구할 수 있다. 양도 통지는 양도인이 해야 하기 때문이다.","c":"상"},"변리사2026_63-30-1":{"f":"전세권 존속 중에는 장래에 그 전세권이 소멸하는 경우에 전세금반환채권이 발생하는 것을 조건으로 그 장래의 조건부 채권을 양도할 수 있다.","w":"전세권 존속 중에도 장래 발생할 전세금반환채권을 조건부로 양도할 수 있다(대법원 판례).","c":"중"},"변리사2026_63-31-1":{"f":"면책적 채무인수가 있으면 종전채무자의 채무에 대한 보증은 보증인의 동의 없이는 소멸한다.","w":"제3자가 제공한 담보는 그 제3자가 동의해야 존속한다(민법 제459조 단서).","c":"상"},"변리사2026_63-31-3":{"f":"면책적 채무인수에서 채권자는 승낙 또는 거절의 의사표시를 채무자나 인수인 중 어느 한쪽에 하면 된다.","w":"승낙이나 거절의 상대방은 채무자와 인수인 중 누구라도 무방하다.","c":"중"},"변리사2026_63-31-4":{"f":"채무자와 인수인의 합의에 의한 중첩적 채무인수에서 채권자의 수익의 의사표시는 그 채무인수 계약의 효력발생을 위한 요건이 아니다.","w":"수익의 의사표시는 성립요건도 효력발생요건도 아니다.","c":"중"},"변리사2026_63-31-5":{"f":"채무자와 인수인이 면책적 채무인수의 약정을 한 경우, 채권자의 승낙이 있어야 채무자는 채무를 면한다.","w":"면책적 채무인수는 채권자의 승낙이 있어야 효력이 생기므로 승낙 없이는 채무자가 면책되지 않는다(민법 제454조).","c":"상"},"변리사2026_63-32-1":{"f":"채권자가 주채무자에 대하여 상계적상이 있는 자동채권을 상계하지 않는 경우에도, 보증인은 이를 이유로 보증채무의 이행을 거절할 수 없다.","w":"보증인이 이행을 거절할 수 있는 사유는 주채무자의 취소권·해제권·해지권이 있는 경우(민법 제435조)이고, 상계적상은 거절 사유가 아니다.","c":"중"},"변리사2026_63-32-2":{"f":"채권자의 연대보증인 중 1인에 대한 채무면제는 연대보증인 사이에 연대특약이 없으면 다른 연대보증인에 대하여 그 효력이 미치지 않는다.","w":"연대보증인 사이에 연대특약이 없으면 그 1인에 대한 면제는 다른 보증인에게 영향을 주지 않는다.","c":"중"},"변리사2026_63-32-3":{"f":"부진정연대채무자 상호간에 구상권을 행사하기 위해서는 사전 또는 사후에 통지를 할 필요가 없다.","w":"통지 의무는 연대채무에 관한 규정(민법 제426조)이고 부진정연대채무에는 적용되지 않는다.","c":"중"},"변리사2026_63-32-4":{"f":"사용대차에서 공동차주는 연대하여 의무를 부담한다.","w":"공동차주는 연대하여 의무를 부담한다(민법 제616조).","c":"상"},"변리사2016_53-33-3":{"f":"공사도급계약의 도급인이 자기 소유의 토지에 근저당권을 설정하여 수급인으로 하여금 공사에 필요한 자금을 대출받도록 한 경우, 수급인의 근저당권말소의무와 도급인의 공사대금채무는 동시이행관계에 있다.","w":"대출 목적으로 설정한 근저당권의 말소의무와 공사대금 지급의무는 서로 대가관계에 있어 동시이행이다.","c":"중"},"변리사2016_53-35-2":{"f":"매도인이 계약금의 배액을 상환하고 계약을 해제하려면 계약해제의 의사표시를 하고 계약금 배액을 제공하면 되고, 상대방이 수령하지 않는 경우에도 공탁까지 할 필요는 없다.","w":"배액을 제공하면 충분하고 공탁은 요구되지 않는다(대법원 판례).","c":"상"},"변리사2016_53-35-3":{"f":"계약당사자가 위 민법규정에 따라 매매계약을 해제하는 경우, 상대방에 대하여 원상회복은 청구할 수 없고 채무불이행을 이유로 한 손해배상도 청구할 수 없다.","w":"해약금에 의한 해제는 채무불이행에 의한 해제가 아니므로 손해배상을 청구할 수 없다(민법 제565조 제2항).","c":"상"},"변리사2016_53-35-4":{"f":"매도인이 매수인에게 매매계약의 이행을 최고하고 매매잔대금의 지급을 구하는 소송을 제기한 것만으로는 이행에 착수한 것이 아니다.","w":"이행 최고나 소송 제기만으로는 이행 착수로 볼 수 없다(대법원 2000.2.11. 선고 판결).","c":"중"},"변리사2016_53-35-5":{"f":"토지거래허가구역 내 토지에 관하여 매매계약을 체결하고 계약금만 주고받은 상태에서 토지거래허가를 받았더라도, 매도인은 해약금규정에 따른 계약해제를 할 수 있다.","w":"허가를 받은 것만으로는 이행 착수가 아니므로 해약금에 의한 해제가 가능하다.","c":"중"},"변리사2016_53-36-2":{"f":"채권자대위권행사의 통지를 받은 후 채무자의 채무불이행을 이유로 제3채무자가 매매계약을 해제한 경우, 그 제3채무자는 계약해제로써 대위권을 행사하는 채권자에게 대항할 수 있다.","w":"법정해제는 채무자의 권리를 처분하는 행위가 아니어서 대위권 행사 통지 후에도 대항할 수 있다.","c":"중"},"변리사2017_54-34-4":{"f":"만약 丙이 甲의 대리인으로서 乙을 기망하여 乙이 위 매매계약을 체결한 경우, 乙은 丙의 대금지급청구를 거절할 수 있을 뿐 아니라 위 매매계약을 취소할 수도 있다.","w":"대리인의 기망은 상대방의 사기와 같이 다루어 취소할 수 있다.","c":"상"},"변리사2017_54-35-1":{"f":"만약 계약 당시 乙이 계약금 5백만원을 지급하였고 약정 계약금이 1천만원이었다면, 계약의 이행 착수 전에 甲은 2천만원을 상환하고 위 매매계약을 해제할 수 있다.","w":"실제 지급된 금액이 아니라 약정 계약금의 배액을 상환해야 한다.","c":"중"},"변리사2017_54-35-2":{"f":"甲의 채권자 丙이 2015. 2. 15. 甲의 잔대금 채권을 가압류한 경우라면, 丙은 민법 제548조 제1항 단서에 의해 보호받을 수 있는 제3자에 해당하지 않는다.","w":"해제된 계약상의 채권을 압류한 자는 해제된 계약의 효과를 기초로 새 권리를 취득한 제3자가 아니다.","c":"중"},"변리사2017_54-35-4":{"f":"","w":"사례의 해제 시점과 임차 시점 선후를 알 수 없어 정확한 결론을 확인할 수 없다. 해제 전에 대항력을 갖춘 임차인은 제3자로 보호되지만, 해제 후 임차인은 보호받지 못한다.","c":"하"},"변리사2017_54-35-5":{"f":"X주택을 사용한 乙이 계약의 해제로 이를 甲에게 반환하는 경우, X주택이 乙의 사용으로 인해 훼손되었다고 볼 수 없는 경우에는 그 사용이익 외에 감가상각비를 별도로 산정하여 반환할 필요가 없다.","w":"사용으로 훼손되지 않았다면 사용이익을 반환하면 족하고, 감가상각비를 따로 가산하지 않는다.","c":"중"},"변리사2017_54-40-1":{"f":"사업자와 고객 사이에 교섭이 이루어진 약관 조항은 「약관의 규제에 관한 법률」에 정한 약관에 해당하지 않는다.","w":"개별적으로 교섭한 합의사항은 약관이 아니다(약관의 규제에 관한 법률 제2조, 제4조).","c":"상"},"변리사2017_54-40-2":{"f":"약관조항이 무효로 되면, 민법상 일부무효의 법리와 달리 나머지 부분은 유효함이 원칙이다.","w":"약관법은 약관의 일부가 무효여도 나머지 부분은 유효하다고 정한다(약관의 규제에 관한 법률 제16조).","c":"상"},"변리사2017_54-40-3":{"f":"약관에 정하여진 사항이 거래상 일반적이고 공통된 것이어서 고객이 별도의 설명 없이도 충분히 예상할 수 있었던 사항이라면, 사업자에게 명시설명 의무가 없다.","w":"설명의무는 고객이 예상하기 어려운 중요 내용에 한해 인정된다.","c":"상"},"변리사2017_54-40-5":{"f":"동일한 약관집 내의 대다수의 조항들이 교섭되고 변경된 사정이 있다면, 변경되지 아니한 나머지 소수의 조항들에 대해서도 교섭이 이루어진 것으로 추정할 수 있다.","w":"대다수 조항이 교섭되었다면 변경되지 않은 조항에도 교섭이 있었다고 추정할 수 있다.","c":"중"},"변리사2018_55-33-1":{"f":"乙이 甲과의 계약을 해제하기 위해서는 이행불능이라면 이행의 최고가 필요하지 않다.","w":"이행불능이면 최고 없이 곧바로 해제할 수 있다(민법 제546조).","c":"중"},"변리사2018_55-33-2":{"f":"乙이 甲과의 계약을 해제하면 乙은 甲에 대해 원상회복청구권을 갖는데, 그 권리의 소멸시효는 해제권이 발생한 때가 아니라 해제를 한 때로부터 진행한다.","w":"원상회복청구권은 해제의 의사표시를 한 때 발생하므로 그때부터 시효가 진행한다.","c":"중"},"변리사2018_55-33-3":{"f":"乙이 甲과의 계약을 해제하기 위해서는 이행불능을 이유로 하는 경우 甲의 소유권이전등기의무와 동시이행관계에 있는 잔대금지급의무의 이행제공을 할 필요가 없다.","w":"이행불능을 이유로 해제할 때에는 상대방이 반대채무를 이행제공할 필요가 없다.","c":"상"},"변리사2018_55-33-4":{"f":"","w":"사례의 구체적 사실관계(이중양도의 대금 지급 상황)를 알 수 없어 정확한 결론을 확인할 수 없다.","c":"하"},"변리사2019_56-33-4":{"f":"계약금을 수령한 매도인이 매수인에 대하여 해제권을 행사하기 위해서는 수령한 계약금의 배액의 이행제공을 하면 되고, 매수인이 수령을 거부하더라도 공탁할 필요는 없다.","w":"배액을 제공하면 해제권을 행사할 수 있고 공탁까지 필요하지는 않다.","c":"중"},"변리사2019_56-34-1":{"f":"甲은 乙이 발송한 편지를 2018. 9. 19. 받았는데, 甲이 2018. 9. 24. 개봉하여 읽었다면 매매계약은 乙이 승낙의 편지를 발송한 때 성립한다.","w":"격지자 사이의 계약은 승낙을 발송한 때 성립하며, 상대방이 읽은 때가 아니다.","c":"중"},"변리사2019_56-34-2":{"f":"乙이 승낙의 의사표시를 하였더라도, 乙이 발송한 편지를 甲이 승낙기간인 2018. 9. 25.까지 받지 못하면 매매계약은 성립하지 않는다.","w":"승낙의 통지가 승낙기간 내에 도달해야 하고 도달하지 않으면 청약이 효력을 잃는다(민법 제528조).","c":"중"},"변리사2019_56-34-3":{"f":"甲은 乙이 발송한 편지를 2018. 9. 20. 받았다면, 매매계약은 乙이 승낙을 발송한 때에 성립하고 효력이 발생한다.","w":"격지자 사이의 계약은 승낙을 발송한 때에 성립한다. 도달한 날이 성립 시기가 아니다.","c":"중"},"변리사2019_56-34-5":{"f":"乙이 2018. 9. 17. 매수하겠다는 편지를 발송하기 전이라도 청약은 철회할 수 없다.","w":"청약은 상대방에게 도달하면 승낙기간이 정해진 때에는 철회할 수 없다(민법 제527조).","c":"중"},"변리사2019_56-35-1":{"f":"근저당권 실행을 위한 경매가 무효로 된 경우, 매수인의 채무자에 대한 소유권이전등기 말소의무와 근저당권자의 매수인에 대한 배당금반환의무는 동시이행관계에 있지 않다.","w":"두 채무는 서로 대가관계가 없어 동시이행관계가 아니다.","c":"중"},"변리사2019_56-35-2":{"f":"동시이행관계에 있는 쌍방의 채무 중 어느 한 채무가 이행불능이 됨으로 인하여 발생한 손해배상채무도 다른 채무와 동시이행관계에 있다.","w":"손해배상채무는 본래 채무의 변형이므로 동일성이 유지되어 동시이행 관계가 유지된다.","c":"상"},"변리사2019_56-35-3":{"f":"가압류등기가 있는 부동산 매매계약의 경우, 특별한 사정이 없는 한 매도인의 가압류 등기의 말소의무는 매수인의 대금지급의무와 동시이행관계에 있다.","w":"가압류 등기 말소는 매도인이 소유권이전과 함께 이행해야 하는 의무이므로 대금지급과 동시이행 관계에 있다.","c":"중"},"변리사2019_56-35-4":{"f":"쌍방의 채무가 동시이행관계에 있는 경우, 상대방 채무의 이행제공이 없으면 채무자가 이행기에 채무를 이행하지 않더라도 이행지체의 책임을 지지 않는다.","w":"동시이행항변권이 있는 동안에는 이행기를 넘겨도 지체책임이 없다.","c":"상"},"변리사2021_58-34-3":{"f":"계약이 의사의 불합치로 성립하지 아니한 경우, 그로 인하여 손해를 입은 당사자는 상대방에 대하여 민법 제535조(계약체결상의 과실)를 유추적용하여 손해배상을 청구할 수 없다.","w":"제535조는 원시적 불능으로 계약이 무효인 경우에 적용되며, 의사 불합치로 계약이 성립하지 않은 경우에는 유추적용되지 않는다.","c":"중"},"변리사2021_58-35-4":{"f":"원인채무의 지급을 담보하기 위하여 어음이 교부된 경우, 채무자는 어음반환과 동시이행을 주장하여 원인채무의 지급을 거절할 수 있다.","w":"담보로 어음을 교부한 경우 어음 반환과 원인채무 이행은 동시이행관계에 있다.","c":"중"},"변리사2021_58-36-1":{"f":"甲과 乙이 계약해제로 인한 원상회복의무로 반환할 매매대금에 가산할 이자를 4%로 약정한 경우, 동 약정이율은 매매대금 반환의무의 이행지체로 인한 지연손해금률에는 적용되지 않는다.","w":"원상회복에 가산하는 이자 약정은 반환의무 이행지체로 인한 지연손해금률과 별개의 약정이다.","c":"중"},"변리사2023_60-34-3":{"f":"요약자와 수익자 사이의 법률관계(대가관계)의 효력 상실을 이유로 요약자는 낙약자와 요약자 사이의 법률관계(기본관계)상 낙약자에게 부담하는 채무의 이행을 거절할 수 없다.","w":"대가관계의 하자는 기본관계에 영향을 주지 않는다.","c":"상"},"변리사2023_60-35-2":{"f":"사정변경을 이유로 한 계약의 해제나 해지에서 사정변경에 대한 예견가능성이 있었는지는 개별적 사정을 고려하여 구체적·개별적으로 판단하여야 한다.","w":"추상적·일반적으로 판단하지 않고, 당사자의 개별 사정을 고려해 구체적으로 판단한다.","c":"중"},"변리사2024_61-33-1":{"f":"의사표시의 불일치로 인해 계약이 성립하지 않는 경우, 그로 인해 손해를 입은 당사자는 계약체결상의 과실로 인한 손해배상을 청구할 수 없다.","w":"계약체결상의 과실 규정(민법 제535조)은 목적이 원시적으로 불능인 경우에 한정되며 의사표시의 불일치에는 적용되지 않는다.","c":"중"},"변리사2024_61-34-1":{"f":"乙의 과실로 도자기가 멸실된 경우, 甲은 도자기 이전의무를 면하면서 얻은 이익이 있다면 이를 乙에게 상환하여야 한다.","w":"채권자의 책임 있는 사유로 이행불능이 되어 채무자가 이익을 얻은 때에는 이를 채권자에게 상환해야 한다(민법 제538조 제2항).","c":"상"},"변리사2026_63-25-1":{"f":"甲에게 乙과의 위 매매계약에 관한 적법한 해제권이 발생하였다면 이후 甲의 과실로 X토지가 현저히 훼손되었을 때에는 甲의 해제권은 소멸한다.","w":"해제권자의 고의나 과실로 목적물이 현저히 훼손되면 해제권이 소멸한다(민법 제553조).","c":"상"},"변리사2026_63-25-2":{"f":"X토지가 토지거래허가구역내의 토지이고 甲과 乙의 매매계약이 주무관청의 허가를 받지 않아 유동적 무효의 상태에 있는 경우, 甲은 乙의 채무불이행을 이유로 위 매매계약을 해제할 수 없다.","w":"유동적 무효 상태의 계약은 아직 효력이 없어 채무불이행을 이유로 해제할 수 없다.","c":"상"},"변리사2026_63-25-3":{"f":"甲의 해제권 행사가 있기 이전에 乙이 丙에게 X토지를 처분함으로써 이후 甲의 해제권 행사에 따른 乙의 원물반환이 불가능하게 된 경우, 乙이 甲에게 원상회복의무로써 반환하여야 할 금액은 처분 당시의 목적물의 대가이다.","w":"반환이 불가능해진 경우의 가액 반환은 처분 당시의 가액을 기준으로 한다.","c":"중"},"변리사2026_63-25-5":{"f":"乙이 甲에 대한 X토지의 소유권이전등기청구권을 丁에게 양도하고 이를 甲에게 통지한 후 甲과 乙의 매매계약이 해제된 경우, 특별한 사정이 없는 한 丁은 민법 제548조 제1항 단서에 의해 보호되는 제3자에 해당하지 않는다.","w":"계약상 채권의 양수인은 해제된 계약의 효과를 기초로 새 권리를 취득한 자가 아니므로 제3자로 보호받지 못한다.","c":"중"},"변리사2026_63-35-4":{"f":"丙의 甲에 대한 대여금채권이 소멸한 경우에도, 乙은 이를 이유로 丙에게 매매대금의 지급을 거절할 수 없다.","w":"수익자와 요약자 사이의 대가관계 소멸은 낙약자가 수익자에게 대항할 수 있는 사유가 아니다.","c":"상"},"변리사2016_53-34-1":{"f":"乙이 丙에 대하여 채무의 이행을 청구하는 소를 제기하였다가 패소한 경우에는 甲은 丙에 대하여 채권자대위권을 행사할 수 없다.","w":"채무자가 이미 권리를 행사해 패소한 경우 채권자가 같은 권리를 대위로 다시 행사할 수는 없다고 본다.","c":"하"},"변리사2016_53-34-2":{"f":"","w":"제3채무자는 채권자의 채권이 시효로 소멸했다고 주장할 수 있다는 것이 현재 판례여서 문장이 틀렸다고 보기 어렵다. 원문의 출제 의도를 확신하지 못한다.","c":"하"},"변리사2016_53-34-3":{"f":"","w":"채권자가 채무자에게 승소 판결을 받았어도 그 기판력은 제3채무자에게 미치지 않아 제3채무자가 피보전채권의 부존재를 주장할 수 있다는 것이 판례여서 문장이 틀렸다고 보기 어렵다. 출제 의도를 확신하지 못한다.","c":"하"},"변리사2016_53-32-2":{"f":"채무자가 채권자에게 채무변제에 갈음하여 다른 채권을 양도하기로 한 경우, 양도인은 양도된 채권의 채무자의 변제자력까지 담보하는 것으로 볼 수 없다.","w":"대물변제로 채권을 양도한 경우 특별한 약정이 없으면 양도인은 채권의 존재만 책임지고 채무자의 변제자력은 담보하지 않는다.","c":"중"},"변리사2017_54-32-3":{"f":"가압류의 효력발생 당시 乙의 채권이 변제기에 도달하지 않은 경우, 甲의 채권의 변제기 후에 乙의 채권이 변제기에 도달한다면 乙은 상계로써 丙에게 대항할 수 없다.","w":"제3채무자의 자동채권 변제기가 압류·가압류된 수동채권의 변제기보다 뒤에 오면 상계로 대항할 수 없다(대법원 2012.2.16. 전원합의체 판결).","c":"상"},"변리사2023_60-32-4":{"f":"피용자의 고의의 불법행위로 인하여 사용자책임이 성립하는 경우, 사용자는 자신의 고의가 없음을 주장하더라도 피해자의 손해배상채권을 수동채권으로 하는 상계권을 행사할 수 없다.","w":"고의의 불법행위로 인한 손해배상채권을 수동채권으로 한 상계는 금지되며(민법 제496조), 사용자책임의 경우에도 사용자가 상계할 수 없다.","c":"중"},"변리사2026_63-33-4":{"f":"채무자로부터 담보부동산을 취득한 후에 채무를 변제한 제3자는 물상보증인에 대하여 채권자를 대위할 수 없다.","w":"제3취득자는 물상보증인에 대하여 채권자를 대위하지 못한다(민법 제482조 제2항 제1호 후단 및 제3호 참조).","c":"중"},"변리사2016_53-34-5":{"f":"甲이 채권자대위권을 행사하는 과정에서 비용을 지출한 경우 甲은 乙에게 그 비용의 상환을 청구할 수 있다.","w":"채권자가 대위권을 행사하는 데 쓴 비용은 위임의 비용상환(민법 제688조)을 준용하여 채무자에게 청구할 수 있다.","c":"상"},"변리사2017_54-27-2":{"f":"채권자대위소송에서 제3채무자는 채권자의 채무에 대한 권리의 발생원인이 된 법률행위가 무효라거나 변제 등으로 소멸하였다는 등의 사실을 주장하여 채권자의 채무자에 대한 권리가 인정되는지를 다툴 수 있다.","w":"제3채무자는 피보전채권의 존부를 다툴 수 있다.","c":"상"},"변리사2017_54-27-3":{"f":"토지거래허가구역에 있는 토지의 매수인은 채권보전의 필요성이 인정되는 경우에 한하여 토지거래허가 신청절차의 협력의무 이행청구권을 보전하기 위하여 매도인의 권리를 대위하여 행사할 수 있다.","w":"채권자대위권은 채권보전의 필요성이 있어야 행사할 수 있다.","c":"중"},"변리사2017_54-27-4":{"f":"이행인수 약정이 체결된 경우, 채무자는 인수인이 그 채무를 이행하지 아니하면 인수인에 대하여 채권자에게 이행할 것을 청구할 수 있고, 채무자의 인수인에 대한 위 청구권을 채권자가 대위행사할 수 있다.","w":"채권자는 자기 채권 보전을 위해 채무자의 이행청구권을 대위하여 행사할 수 있다.","c":"중"},"변리사2017_54-27-5":{"f":"지하도상가 내 점포의 사용청구권을 가지는 자는 상가의 소유자인 시(市)가 불법점유자들에 대하여 가지는 점포의 인도청구권을 대위행사할 수 있다.","w":"특정 점포의 사용청구권을 가진 사람은 소유자의 인도청구권을 대위 행사할 수 있다.","c":"중"},"변리사2017_54-28-4":{"f":"","w":"채권양도 취소와 원상회복에 따른 제3채무자에 대한 통지 후 채권자가 채무자를 대위해 지급을 청구할 수 있는지는 판례 세부를 확신하지 못한다.","c":"하"},"변리사2018_55-26-1":{"f":"채무자의 법률행위가 통정허위표시로 무효인 경우에도 채권자취소권의 대상이 될 수 있다.","w":"허위표시로 무효여도 채권자취소권의 요건을 갖추면 사해행위로 취소할 수 있다.","c":"상"},"변리사2018_55-26-2":{"f":"매매계약을 원인으로 하는 가등기에 기하여 본등기가 경료된 경우, 사해행위 요건의 구비 여부는 특별한 사정이 없는 한 가등기를 한 시점을 기준으로 판단하여야 한다.","w":"본등기는 가등기 순위를 확정하는 것이어서 사해행위는 가등기를 한 시점의 원인행위를 기준으로 판단한다(대법원 판례).","c":"중"},"변리사2018_55-26-4":{"f":"채무자가 저당권이 설정되어 있는 자신의 유일한 재산을 양도한 경우, 저당권의 피담보채권액이 그 재산의 가액을 초과하면 당해 재산의 양도는 사해행위에 해당하지 않는다.","w":"피담보채권액이 가액을 넘으면 일반채권자의 공동담보에 남는 책임재산이 없어 사해행위가 되지 않는다.","c":"상"},"변리사2018_55-26-5":{"f":"채권자가 채무자와 수익자 사이의 부동산매매계약을 사해행위로 취소함에 따라 수익자 명의의 소유권이전등기가 말소되어 채무자의 등기명의가 회복된 경우, 채무자가 그 부동산을 제3자에게 처분하더라도 이는 무권리자의 처분으로서 효력이 없다.","w":"취소의 효력은 상대적이어서 채무자는 소유권을 취득하지 못하고, 처분해도 무권리자의 처분이다.","c":"중"},"변리사2021_58-32-5":{"f":"乙의 채권자 戊가 2020. 12. 3. 乙 소유의 X부동산을 가압류한 상태에서, 2021. 1. 15. 乙로부터 X부동산을 양도받은 丙이 乙의 戊에 대한 가압류채무를 변제한 경우, X부동산의 양도계약이 사해행위로 취소되면 丙은 특별한 사정이 없는 한 甲에게 가액반환을 하여야 하고, 위 변제액은 공제하지 않는다.","w":"가압류 채무를 변제했다고 해서 취소채권자에게 반환할 가액에서 그 금액을 공제하는 것은 아니다.","c":"하"},"변리사2023_60-26-1":{"f":"채권자는 피보전채권의 변제기 전이라도 채권자대위권을 행사해서 피대위채권의 시효중단을 위한 이행청구를 할 수 있다.","w":"시효중단은 보존행위이므로 변제기 전에도 대위로 이행청구할 수 있다(민법 제404조 제2항 단서).","c":"상"},"변리사2023_60-26-2":{"f":"임대인의 동의없는 임차권의 양도는 당사자 사이에서는 유효하더라도 임차권의 양수인은 임대인의 권한을 대위 행사할 수 없다.","w":"임차권 양수인이 임대인에게 동의를 구하는 방법으로 대위할 수는 없다.","c":"중"},"변리사2023_60-26-4":{"f":"채권자가 채무자의 토지 소유권이전등기청구권을 대위행사한 후 이를 채무자에게 통지한 경우, 채무자가 그 토지 소유권을 이전받는 것은 처분권제한에 위배되지 않아 유효하다.","w":"채무자가 등기를 이전받는 행위는 권리의 처분이 아니므로 대위 행사 통지 후에도 유효하다.","c":"중"},"변리사2023_60-26-5":{"f":"제3채무자가 직접 대위채권자에게 금전을 지급하도록 하는 채권자대위소송의 판결이 확정된 경우, 대위채권자의 채권자가 아니라 채무자의 다른 채권자가 대위채권자가 제3채무자로부터 지급받을 금전을 압류할 수 있다.","w":"채무자의 채권자만 압류·가압류할 수 있다. 대위채권자의 채권자는 아니다.","c":"중"},"변리사2023_60-27-5":{"f":"취소채권자는 수익자가 사해행위로 취득한 근저당권에 배당된 배당금을 가압류한 수익자의 채권자에 대하여 우선하여 배당을 받을 수 없다.","w":"채권자취소권의 취소 효과로 우선변제권이 생기는 것이 아니므로 다른 채권자와 평등하게 배당된다.","c":"중"},"변리사2024_61-28-3":{"f":"취득시효의 대상인 부동산의 소유자가 취득시효 완성 후에 그 부동산을 처분하여 점유자의 시효취득을 원인으로 한 소유권이전등기청구권이 침해된 경우, 그 점유자는 소유권이전등기청구권의 보전을 위해 채권자취소권을 행사할 수 없다.","w":"채권자취소권은 금전채권을 보전하는 제도이고 특정물에 대한 이전등기청구권을 보전하기 위해서는 행사할 수 없다.","c":"상"},"변리사2026_63-28-5":{"f":"비법인사단이 총유재산에 관한 권리를 행사하지 않고 있어 비법인사단의 채권자가 그 권리를 대위행사하는 경우에는 사원총회의 결의를 거칠 필요가 없다.","w":"채권자가 대위로 행사하는 것이어서 사원총회 결의가 필요하지 않다.","c":"중"},"변리사2026_63-29-3":{"f":"사해행위 이전에 성립한 채권이 사해행위 이후에 양도되었더라도 그 채권양수인은 채권자취소권을 행사할 수 있다.","w":"피보전채권이 사해행위 전에 성립했다면 이후에 양도되어도 양수인이 행사할 수 있다.","c":"상"},"변리사2016_53-37-5":{"f":"건축주 사정으로 공사가 중단된 미완성의 건물을 인도받아 완공하였더라도, 그 건물이 공사 중단 시점에서 사회통념상 독립한 건물이라고 볼 수 있는 형태와 구조를 갖추고 있었다면 완공자가 그 건물의 소유권을 원시취득하지 못한다.","w":"이미 독립한 건물로서 형태를 갖춘 상태에서 인도받았다면 최초 건축주가 소유권을 취득한 것이고 완공자는 원시취득하지 못한다(대법원 판례).","c":"중"},"변리사2016_53-38-1":{"f":"조합원 중에 변제할 자력이 없는 자가 있는 때에는 그 변제할 수 없는 부분은 다른 조합원이 균분하여 변제할 책임이 있다.","w":"조합원 중 무자력자의 부담 부분은 다른 조합원이 균분하여 변제한다(민법 제713조). 출자가액 비례가 아니다.","c":"상"},"변리사2017_54-33-1":{"f":"乙의 차임채무불이행으로 임대차가 종료된 경우에는 乙은 甲에게 Y건물의 매수를 청구할 수 없다.","w":"임차인의 채무불이행으로 임대차가 해지된 경우에는 지상물매수청구권이 생기지 않는다.","c":"상"},"변리사2017_54-33-2":{"f":"乙이 적법하게 Y건물의 매수를 청구한 경우, 甲의 대금지급의무는 乙의 Y건물 명도 및 소유권이전의무와 동시이행관계에 있다.","w":"매수청구 후 대금 지급과 건물 명도·이전등기는 동시에 이행한다.","c":"상"},"변리사2017_54-33-3":{"f":"乙이 Y건물에 대한 보존등기를 마친 후 甲이 丙에게 X토지를 매도하고 소유권이전등기를 마쳐 준 경우, 乙의 임차권이 기간만료로 소멸하면 乙은 丙을 상대로 Y건물의 매수를 청구할 수 있다.","w":"임차권이 대항력을 갖춘 이상 새 소유자 丙에게도 매수청구를 할 수 있다.","c":"중"},"변리사2017_54-33-4":{"f":"만약 乙의 채권자 명의로 근저당권이 설정된 Y건물에 대하여 乙이 적법하게 매수청구권을 행사한 경우, 甲은 근저당권이 말소되지 않았음을 이유로 채권최고액에 상당한 대금의 지급을 거절할 수 있다.","w":"건물에 설정된 근저당권의 말소와 대금 지급은 동시이행 관계에 있어 근저당이 말소되지 않았다면 일부 지급을 거절할 수 있다.","c":"중"},"변리사2018_55-34-2":{"f":"","w":"임차인의 차임연체로 임대차가 해지된 뒤 인도·연체차임을 구하는 소송비용을 보증금에서 공제할 수 있는지에 관해 판례 결론을 확신하지 못한다.","c":"하"},"변리사2018_55-39-1":{"f":"매도인이 계약과 동시에 환매할 권리를 보류한 때에는 환매대금은 매도인이 영수한 대금 및 매수인이 부담한 매매비용으로 하되, 당사자가 특약으로 환매대금을 다르게 정할 수 있다.","w":"환매대금에 관한 특약은 허용된다(민법 제590조 제2항 단서).","c":"상"},"변리사2019_56-37-3":{"f":"甲과 乙 사이의 임대차계약은 무단전대를 이유로 甲이 해지의 의사표시를 하여야 해지의 효력이 발생한다.","w":"무단전대를 이유로 한 해지는 임대인의 의사표시가 있어야 하고 당연히 해지되는 것은 아니다(민법 제629조 제2항).","c":"상"},"변리사2019_56-37-5":{"f":"甲과 乙 사이의 임대차계약이 존속하는 한 甲은 X토지의 불법점유를 이유로 丙에게 차임상당의 부당이득반환을 청구할 수 없다.","w":"임대차가 존속하는 동안 임대인은 임차인에게서 차임을 받을 수 있어 전차인에게 부당이득반환을 청구할 수 없다.","c":"중"},"변리사2019_56-39-1":{"f":"조합원은 조합의 업무집행자가 아니더라도 조합의 업무 및 재산상태를 검사할 수 있다.","w":"조합원은 정당한 사유가 없어도 업무와 재산 상태를 검사할 수 있다(민법 제710조).","c":"상"},"변리사2019_56-39-3":{"f":"조합원의 제명은 정당한 사유가 있는 때에 한하여 다른 조합원의 일치로 결정된다.","w":"제명은 정당한 사유가 있고 다른 조합원의 일치가 있어야 한다(민법 제718조 제1항).","c":"상"},"변리사2019_56-39-4":{"f":"조합의 채무자는 그 채무와 조합원에 대하여 개인적으로 가지는 채권과 상계할 수 없다.","w":"조합의 채권과 조합원 개인에 대한 채권은 당사자가 다르므로 상계할 수 없다(민법 제715조).","c":"상"},"변리사2019_56-39-5":{"f":"조합원의 제명 결정은 제명된 조합원에게 통지하지 아니하면 그 조합원에게 대항하지 못한다.","w":"제명 결정은 제명된 조합원에게 통지해야 그에게 대항할 수 있다(민법 제718조 제2항).","c":"상"},"변리사2021_58-39-1":{"f":"어느 조합원이 출자의무를 이행하지 않은 경우, 다른 조합원은 이를 이유로 조합계약을 해제할 수 없다.","w":"조합계약에는 해제가 적용되지 않고 탈퇴·제명·해산청구로 해결한다.","c":"상"},"변리사2021_58-39-3":{"f":"부동산의 공동매수인들이 전매차익을 얻으려는 목적으로만 상호 협력하는 경우에는 민법상 조합관계에 있다고 볼 수 없다.","w":"공동사업 경영이 없이 각자 이익을 얻을 목적으로 협력하는 관계는 조합이 아니다.","c":"중"},"변리사2021_58-39-4":{"f":"조합원의 채권자는 조합재산을 구성하는 개개의 재산에 대한 조합원의 합유지분에 대하여 강제집행을 할 수 없다.","w":"합유지분은 처분이 제한되므로 개별 재산에 대한 합유지분을 압류할 수 없다.","c":"상"},"변리사2021_58-39-5":{"f":"조합원이 조합을 탈퇴할 권리는 그 성질상 채권자대위가 허용되지 않는 일신전속적 권리에 해당하지 않는다.","w":"조합 탈퇴권은 재산적 성질이 있어 채권자대위의 대상이 될 수 있다.","c":"상"},"변리사2021_58-40-1":{"f":"수량지정매매에 해당하는 부동산매매계약에서 실제면적이 계약면적에 미달하는 경우, 매수인은 대금감액청구권의 행사와 별도로 부당이득반환청구를 할 수 없다.","w":"면적 부족은 담보책임으로 대금감액을 청구하는 것이어서 부당이득반환을 따로 청구할 수 없다.","c":"중"},"변리사2023_60-38-1":{"f":"조합재산을 구성하는 개개의 재산에 대한 합유지분을 압류 기타 강제집행의 대상으로 삼을 수 없다.","w":"합유지분은 조합 전체의 동의 없이 처분할 수 없어 강제집행의 대상이 되지 않는다.","c":"상"},"변리사2023_60-38-2":{"f":"2인으로 구성된 조합에서 1인이 탈퇴하여 조합관계가 종료되는 경우, 특별한 사정이 없는 한 해산이나 청산을 거치지 않고 조합재산은 남은 조합원의 단독소유에 속하게 된다.","w":"2인 조합에서 1인이 탈퇴하면 조합관계가 소멸하고, 재산은 남은 조합원의 단독소유가 된다.","c":"상"},"변리사2023_60-38-3":{"f":"2인으로 구성된 조합에서 1인이 존속기한을 정하지 않고 부동산 사용권을 출자하였다가 탈퇴한 경우, 특별한 사정이 없는 한 탈퇴 시 남은 조합원의 부동산 사용권은 소멸하지 않는다.","w":"출자한 부동산 사용권은 탈퇴로 소멸하지 않고 남은 조합원이 계속 사용할 수 있다.","c":"중"},"변리사2023_60-38-4":{"f":"공동이행방식의 건설공동수급체의 구성원인 조합원이 그 출자의무를 불이행하더라도, 특별한 사정이 없는 한 출자의무의 불이행을 이유로 이익분배 자체를 거부할 수 없다.","w":"출자의무 불이행은 별도의 손해배상으로 해결하며 이익분배를 거부할 사유는 아니다.","c":"중"},"변리사2024_61-35-1":{"f":"부담부 증여에서 상대방의 부담의무 불이행을 이유로 한 증여자의 계약해제는 이미 이행한 부분에 대하여도 효력이 미친다.","w":"부담부 증여에는 쌍무계약 규정이 준용되어 해제하면 원상회복을 청구할 수 있다.","c":"중"},"변리사2024_61-37-5":{"f":"수임인이 위임인의 지명에 의하여 복수임인을 선임한 경우, 수임인은 부적임 또는 불성실함을 알고 위임인에 대한 통지나 그 해임을 게을리한 때에 한하여 책임을 진다.","w":"위임인이 지명한 복수임인에 관해서는 선임·감독 책임이 없고, 부적임·불성실을 알고도 통지나 해임을 게을리한 경우에만 책임이 있다(민법 제682조 제2항, 제121조 제2항).","c":"상"},"변리사2026_63-37-2":{"f":"甲이 乙의 사용수익권을 보장하기 위하여 X건물을 수선한 경우, 그 수선기간 동안 乙의 사용수익에 지장이 생겼다면 乙은 그 지장의 한도에서 차임의 지급을 거절할 수 있다.","w":"임대인의 수선 때문에 사용수익이 방해된 범위에서는 차임 지급을 거절할 수 있다.","c":"중"},"변리사2026_63-37-3":{"f":"임대차계약의 체결 당시에 乙이 필요비상환청구권을 미리 포기하기로 약정한 경우, 특별한 사정이 없는 한 이러한 약정은 유효하다.","w":"필요비상환청구권은 임의규정이므로 포기 약정은 유효하다.","c":"중"},"변리사2026_63-37-5":{"f":"甲이 丁에게 X건물을 양도하고 소유권등기를 이전한 후 X건물의 임대차가 종료되어 丁이 乙에게 임대차보증금을 반환하여야 하는 경우, 丁이 甲의 지위를 승계하기 전까지 발생한 연체차임은 채권양도의 요건을 갖추지 않아도 임대차보증금에서 당연히 공제된다.","w":"양수인이 임대인 지위를 승계하면 양도 전 연체차임도 보증금에서 공제된다. 임차인의 차임 연체는 임대차 종료 때 보증금에서 당연히 공제되기 때문이다.","c":"중"},"변리사2026_63-38-1":{"f":"乙이 직접 X건물을 건축하지 않고 이행대행자로서 丙을 사용하였더라도 특별한 사정이 없는 한 乙은 도급계약을 불이행한 것으로 볼 수 없다.","w":"수급인은 일의 완성에 책임을 지고, 특별한 사정이 없으면 이행보조자를 쓸 수 있다.","c":"상"},"변리사2016_53-39-1":{"f":"사무관리의 성립요건인 ‘타인을 위하여 사무를 처리하려는 의사’는 관리자 자신의 이익을 도모하려는 의사와 병존할 수 있다.","w":"타인을 위한 의사가 인정되면 자신을 위한 의사와 함께 있어도 사무관리가 성립한다.","c":"상"},"변리사2016_53-39-3":{"f":"사무관리자가 본인의 의사에 반하여 사무를 관리한 때에는 본인의 현존이익의 한도에서 비용의 상환을 청구할 수 있다.","w":"본인의 의사에 반한 사무관리는 현존이익 한도에서 비용을 청구할 수 있다(민법 제734조 제3항).","c":"상"},"변리사2016_53-39-4":{"f":"사무관리자는 본인에 대하여 비용의 상환을 청구할 수 있을 뿐, 사무관리에 의하여 결과적으로 사실상 이익을 얻은 다른 제3자에 대하여 직접 부당이득반환을 청구할 수는 없다.","w":"상환 청구는 본인에게만 할 수 있고, 제3자에게 직접 부당이득반환을 청구할 수 없다.","c":"중"},"변리사2016_53-39-5":{"f":"사무관리 관계는 본인이 스스로 그 사무를 관리할 수 있게 된 때에 종료하며, 본인의 명시적 의사표시가 반드시 필요한 것은 아니다.","w":"본인이 사무를 관리할 수 있게 될 때까지 관리를 계속하는 것이 원칙이고, 종료 사유는 이것이다.","c":"중"},"변리사2016_53-40-2":{"f":"고의의 불법행위를 원인으로 한 부당이득반환채권을 수동채권으로 하는 상계는 허용되지 않는다.","w":"고의 불법행위로 인한 채권을 수동채권으로 하는 상계는 금지된다(민법 제496조).","c":"중"},"변리사2017_54-37-1":{"f":"사무처리의 긴급성 등으로 국가의 사무에 대하여 사인의 개입이 정당화되는 경우, 사인은 국가의 사무를 처리하면서 지출한 필요비뿐 아니라 유익비의 상환도 청구할 수 있다.","w":"사무관리의 비용상환 대상에는 유익비도 포함된다.","c":"중"},"변리사2018_55-35-4":{"f":"甲이 乙에게 부동산을 매도하고 목적물을 인도하지 않은 상태에서 乙로부터 중도금까지 받았으나 매매계약이 처음부터 무효였다면, 甲이 선의라면 받은 날로부터 이자를 가산하지 않고 받은 금전을 반환하면 된다.","w":"선의의 수익자는 이익이 현존하는 한도에서 반환하며(민법 제748조 제1항), 받은 날부터 이자를 가산할 의무는 없다.","c":"중"},"변리사2023_60-39-3":{"f":"과세관청이 3자간 등기명의신탁에 따라 해당 부동산의 공부상 소유자가 된 명의수탁자에게 재산세 부과처분을 하여 명의수탁자가 재산세를 납부한 경우, 그는 명의신탁자나 그 상속인을 상대로 재산세 상당액에 대한 부당이득반환청구를 할 수 없다.","w":"재산세는 공부상 소유자가 부담하는 세금이어서 수탁자가 낸 세금을 신탁자에게서 돌려받을 수 없다.","c":"중"},"변리사2024_61-38-1":{"f":"관리자가 사무의 적절한 관리를 함에 있어 과실없이 손해를 받은 때에는 본인의 현존이익의 한도에서 그 손해의 보상을 청구할 수 있다.","w":"손해 전액이 아니라 본인의 현존이익 한도이다(민법 제740조).","c":"상"},"변리사2024_61-38-2":{"f":"관리자가 본인을 위하여 본인의 의사에 부합하게 사무를 관리하면서 유익비를 지출한 경우, 지출한 비용과 이자를 청구할 수 있다.","w":"본인의 의사에 합치하면 유익비를 지출한 전액과 지출 이후 이자를 청구할 수 있다(민법 제739조 제1항).","c":"중"},"변리사2024_61-38-3":{"f":"상대방과의 약정에 따라 제3자의 사무를 관리한 경우, 그 관리자와 제3자 사이에서는 원칙적으로 사무관리가 성립하지 않는다.","w":"계약상 의무에 따른 관리는 사무관리가 아니라 그 계약 관계로 처리한다.","c":"상"},"변리사2024_61-38-4":{"f":"관리자에게 타인을 위해 사무를 처리하는 의사와 관리자 자신의 이익을 위한 의사가 모두 있는 경우에도 사무관리가 성립할 수 있다.","w":"두 의사가 병존해도 사무관리가 성립한다.","c":"상"},"변리사2026_63-39-3":{"f":"채권자가 채무자에게 지급되어야 할 대상(代償)청구의 대상이 되는 보상금을 어떤 사유로 직접 자신의 명의로 지급받았더라도 채무자에 대한 관계에서 바로 부당이득이 되는 것은 아니다.","w":"채권자가 지급받은 사정만으로 채무자에게 반환할 부당이득이 생기는 것은 아니다.","c":"중"},"변리사2017_54-38-2":{"f":"","w":"사례의 구체적 사실관계(책임비율)를 알 수 없어 정확한 결론을 확인할 수 없다.","c":"하"},"변리사2018_55-36-5":{"f":"피용자와 제3자와의 공동불법행위로 인해 손해를 입은 피해자에게 사용자가 채권을 가지고 있으나 사용자가 상계할 수 있음에도 상계하지 않는 경우, 제3자는 사용자의 채권을 가지고 피해자에게 상계할 수 없다.","w":"제3자는 사용자의 채권으로 상계할 권한이 없다.","c":"중"},"변리사2019_56-40-5":{"f":"공동불법행위자 중 1인인 甲의 손해배상채무가 시효로 소멸한 후에도, 다른 공동불법행위자 乙이 피해자에게 자기의 부담부분을 넘는 손해를 배상하였다면 乙은 甲에게 구상권을 행사할 수 있다.","w":"구상권은 변제로 새로 생기는 별개의 채권이어서 피해자에 대한 채무가 시효로 소멸했더라도 구상할 수 있다.","c":"중"},"변리사2023_60-40-1":{"f":"공동불법행위자들 중에 고의로 불법행위를 행한 자가 있는 경우에도, 과실에 그친 공동불법행위자는 과실상계를 주장할 수 있다.","w":"과실상계는 각 공동불법행위자에 대해 따로 판단한다. 고의의 불법행위자는 과실상계를 주장할 수 없다.","c":"중"},"변리사2024_61-39-1":{"f":"공동불법행위자 甲과 乙중 甲의 손해배상채무가 시효로 소멸한 후에 乙이 피해자에게 자기의 부담 부분을 넘는 손해를 배상한 경우, 乙은 甲을 상대로 구상권을 행사할 수 있다.","w":"구상권은 변제 시 새로 발생하는 권리로, 甲의 채무가 소멸시효로 소멸했어도 행사할 수 있다.","c":"중"},"변리사2024_61-39-2":{"f":"자신의 과실에 의해 초래된 급박한 위난을 피하기 위해 부득이 타인에게 손해를 가한 자는 그 손해에 대한 배상책임을 진다.","w":"위난이 자신의 과실로 생긴 경우에는 긴급피난이 적용되지 않아 배상책임을 면하지 못한다(민법 제761조 제2항).","c":"상"},"변리사2024_61-39-4":{"f":"피용자와 제3자가 공동불법행위에 따른 손해배상채무를 부담하는 경우, 사용자가 피용자와 제3자의 책임비율에 의해 정해진 부담부분을 초과하여 피해자에게 배상하면 제3자에 대하여 구상권을 행사할 수 있다.","w":"사용자도 피용자의 부담부분을 넘어 배상한 경우 제3자에게 구상할 수 있다.","c":"상"},"변리사2024_61-39-5":{"f":"불법행위로 인하여 건물이 훼손되어 사용 및 수리가 불가능한 경우, 손해배상액의 기준이 되는 건물의 시가에는 원칙적으로 건물의 철거비용이 포함되지 않는다.","w":"건물이 사용 불가능한 때에는 시가에서 철거비용을 공제한 금액을 손해액으로 본다.","c":"중"},"변리사2026_63-40-1":{"f":"피용자의 고의에 의한 불법행위로 인하여 사용자가 사용자책임을 부담하는 경우, 사용자책임의 범위를 정함에 있어서 피해자의 과실을 고려하여 그 책임을 제한할 수 있다.","w":"피용자가 고의로 불법행위를 해도 사용자책임에서는 피해자의 과실을 참작할 수 있다.","c":"상"},"변리사2016_53-01":{"w":"ㄱ O. 계약 성립의 기초가 되지 않은 사정이 후에 변경되어 일방이 계약 목적을 달성하지 못해 손해를 입어도, 특별한 사정이 없으면 사정변경을 이유로 한 해제는 인정되지 않는다.\nㄴ X. 채무액과 변제기가 특정된 회사 채무를 보증한 이사는 이사직 사임을 이유로 보증계약을 일방적으로 해지할 수 없다.\nㄷ O. 신의칙 위반과 권리남용은 강행규정 위반이므로 당사자의 주장이 없어도 법원이 직권으로 판단한다.\nㄹ X. 강행법규를 위반한 자가 스스로 그 약정의 무효를 주장해도 특별한 사정이 없으면 신의칙에 반하지 않는다.\n따라서 ㄱ, ㄷ인 ②.","c":"상"},"변리사2016_53-02":{"w":"⑤가 틀리다. 한정후견인의 동의가 필요한 행위에서 피한정후견인의 이익이 침해될 염려가 있는데도 한정후견인이 동의하지 않으면 가정법원이 동의에 갈음하는 허가를 할 수 있고(민법 제13조 제3항), 그 허가 없이 한 행위는 한정후견인이 취소할 수 있다(제13조 제4항).\n①은 판례(신용구매계약, 미성년자 취소 가능), ②는 묵시적 동의 가능, ③은 제10조 제4항(일용품 구입 등은 취소 불가), ④는 취소할 수 없는 범위의 행위이므로 유효하다.","c":"상"},"변리사2016_53-03":{"w":"⑤가 옳다. 제35조의 직무관련성은 행위의 외형을 객관적으로 보아 판단한다.\n①은 대표권 없는 이사의 행위로는 제35조 책임이 생기지 않는다. ②는 법인을 실질적으로 운영하며 사실상 대표하는 자의 행위도 법인의 불법행위가 된다. ③은 감사는 대표기관이 아니므로 성립하지 않는다. ④는 대표기관의 행위가 법인의 목적 범위 외라면 법인의 불법행위로 되지 않는다.","c":"중"},"변리사2017_54-01":{"w":"②가 틀리다. 미등기 무허가건물의 매수인에게는 소유권이전등기 없이 소유권에 준하는 관습상 물권이 인정되지 않는다(판례).\n①은 관습법의 법원성, ③은 종중 명칭이 관습에 어긋나도 실체는 부인되지 않음, ④⑤는 사실인 관습이 임의규정 영역에서 법률행위 해석기준이 되며 제정법과 배치될 때는 당사자의 주장 증명과 임의규정 여부 심리가 필요하다는 판례 그대로이다.","c":"중"},"변리사2017_54-02":{"w":"옳지 않은 것은 ㄱ, ㄴ이다.\nㄱ X. 실종선고 청구권자인 이해관계인은 법률상 이해관계가 있는 사람이다. 상속에서 배우자 乙과 직계비속 丁은 1순위이고 직계존속 丙은 후순위여서 이해관계인에 해당하지 않는다.\nㄴ X. 사망간주 시점(2014. 5. 20.) 이후인 2016. 5. 10. 이혼판결이 확정되었더라도, 그 이혼판결은 확정 당시 유효하고 실종선고의 소급 효과로 무효가 되지 않는다는 취지로 푼다.\nㄷ O. 실종선고가 취소되기 전에는 그에 따른 상속은 유효하다(제29조 제1항 본문 취지).\n정답 ③. ㄱ은 상속순위 논리로 풀었고 ㄴ은 판례 내용을 확인하지 못했다.","c":"하"},"변리사2017_54-03":{"w":"ㄱ X. 비법인사단 대표자는 정관이나 총회 결의로 허용되지 않는 한 업무 전반을 포괄적으로 위임할 수 없고, 이 경우 수임인의 대행행위는 비법인사단에 효력이 없다.\nㄴ X. 비법인사단도 명예권의 주체가 되어 명예훼손에 대한 손해배상을 청구할 수 있다.\nㄷ O. 대표자의 행위가 직무에 관한 것이 아님을 피해자가 알았거나 중대한 과실로 알지 못한 때에는 제35조 책임을 물을 수 없다.\nㄹ O. 법령에 위배되는 행위여도 외관상 객관적으로 직무에 관한 행위이면 제35조 제1항 책임이 인정된다.\n정답 ④.","c":"중"},"변리사2018_55-08":{"w":"ㄱ O. 채무액과 변제기가 특정된 회사 채무의 보증은 이사직 사임을 이유로 일방 해지할 수 없다.\nㄴ X. 소멸시효 완성 주장이 권리남용이어서 국가가 배상한 경우에도, 사건 은폐조작 등 원인행위를 적극 주도한 공무원에 대한 국가의 구상권 행사는 신의칙상 허용된다.\nㄷ O. 대표권 남용에서 상대방이 그 사정을 알았거나 알 수 있었던 경우 회사는 상대방의 악의 등을 증명해 효과를 부인할 수 있다(제107조 제1항 단서 유추).\nㄹ X. 상대방이 고지 대상 사실을 이미 알고 있으면 고지의무는 없다.\nㅁ O. 경험칙상 고지받았다면 거래하지 않았을 것이 명백한 사정은 신의칙상 고지할 의무가 있다.\n정답 ③.","c":"중"},"변리사2019_56-01":{"w":"ㄱ O. 사정변경에 따른 해제는 계약준수 원칙의 예외이다.\nㄴ O. 사용자는 신의칙상 부수의무로 근로자의 건강을 해치지 않도록 필요한 조치를 해야 한다.\nㄷ O. 채권자가 제3자 부동산을 채무자에게 명의신탁하게 한 뒤 강제집행하는 것은 신의칙상 허용되지 않는다.\nㄹ O. 분양자는 인근 쓰레기 매립장 건설 예정 사실을 분양계약자에게 고지할 신의칙상 의무가 있다.\n모두 옳아 ⑤.","c":"상"},"변리사2021_58-01":{"w":"ㄱ O. 채무자가 시효완성 전에 채권자의 권리행사를 현저히 곤란하게 하여 시효가 완성되었다면 시효 완성 주장은 권리남용이다.\nㄴ O. 권리남용은 당사자 주장이 없어도 법원이 직권으로 판단할 수 있다.\nㄷ O. 유치권을 고의로 작출해 최우선순위 담보권의 지위를 부당하게 이용하는 것은 신의칙에 반하는 유치권의 남용이다.\nㄹ X. 권리남용의 효과는 권리의 종류와 남용의 결과에 따라 달라서 모두 권리 박탈로 귀결되지는 않는다(행사 불허, 손해배상 등).\n정답 ④.","c":"상"},"변리사2021_58-02":{"w":"ㄱ O. 정관에 이사 해임사유가 규정되어 있으면 중대한 의무위반 등 특별한 사정이 없는 한 그 밖의 사유로 해임할 수 없다(판례).\nㄴ X. 이사의 성명·주소는 등기사항이지만(제49조 제2항) 감사는 등기사항이 아니다.\nㄷ O. 법인과 이사의 이익이 상반되는 사항은 특별대리인이 법인을 대표한다(제64조).\nㄹ X. 이사의 대표권 제한은 정관에 기재해야 하고(제41조) 등기하지 않으면 선의·악의를 가리지 않고 제3자에게 대항하지 못한다(제60조).\n정답 ①.","c":"중"},"변리사2023_60-01":{"w":"③이 옳다. 실종선고가 취소되면 선의로 행위한 자의 행위는 유효하고, 선의의 수령자는 현존이익 한도에서 반환한다(제29조 제2항).\n①은 사망 간주 시점이 실종기간 만료 시(2015. 9. 15.부터 5년이 지난 때)이지 선고 시점이 아니다(제28조). ②는 실종선고가 취소되기 전에는 반환을 구할 수 없다. ④는 선거권 판례를 확인하지 못해 정답 ③과 비교해서만 판단했다. ⑤는 취소의 효력이 소급한다(다만 선의 행위는 유효).","c":"하"},"변리사2024_61-02":{"w":"ㄱ X. 비법인사단 대표자가 대표자로서의 모든 권한을 포괄적으로 위임한 것은 허용되지 않고, 그 수임인의 대행행위는 원칙적으로 비법인사단에 효력이 없다.\nㄴ O. 실질적으로 대표자로 행위한 乙의 사무집행 중 불법행위에 대해 비법인사단은 제35조 책임을 진다.\nㄷ X. 사익을 도모한 행위여도 외관상 객관적으로 직무에 관한 행위이면 직무관련성이 인정된다(상대방이 악의 또는 중과실이면 예외).\nㄹ O. 대표 권한을 전부 위임하고 직무를 전혀 집행하지 않은 것은 그 자체로 이사의 선관주의의무 위반이다.\n정답 ③.","c":"중"},"변리사2024_61-03":{"w":"ㄱ X. 의사무능력자의 법률행위는 무효이고, 무능력을 이유로 한 무효 주장이 신의칙에 반하지는 않는다.\nㄴ O. 의사무능력자는 선의·악의를 가리지 않고 받은 이익이 현존하는 한도에서 반환한다(제141조 단서 유추, 판례).\nㄷ O. 甲의 丙에 대한 부당이득반환채권 양도의무와 乙의 저당권등기 말소의무는 동시이행관계에 있다(판례).\n정답 ④.","c":"중"},"변리사2026_63-01":{"w":"ㄱ O. 차임불증액 특약이 있어도 특약을 유지하는 것이 신의칙에 반할 정도의 사정변경이 있으면 임대인의 차임증액청구가 인정된다.\nㄴ O. 채무액과 변제기가 특정된 회사채무의 보증은 이사직 사임을 이유로 일방 해지할 수 없다.\nㄷ X. 임대차 체결 시 지상물 포기 약정은 지상물매수청구권(제643조, 제652조)에 반하는 약정으로 무효이므로, 임차인의 매수청구권 행사가 신의칙에 반하지 않는다.\n정답 ③.","c":"상"},"변리사2023_60-04":{"w":"⑤가 종물 관계가 아니다. 주유소 부지 지하에 매설된 유류저장탱크는 토지에 부합된 것이지 독립한 물건인 종물이 아니다(판례).\n배와 노, 자물쇠와 열쇠, 주유소건물과 주유기, 횟집과 수족관은 종물이다(제100조).","c":"중"},"변리사2016_53-07":{"w":"④가 틀리다. 보통우편으로 발송한 경우 발송 사실만으로는 도달이 추정되지 않고, 도달 사실은 이를 주장하는 쪽이 증명해야 한다.\n①②③은 도달이 상대방이 내용을 알 수 있는 객관적 상태에 놓인 때라는 판례이고, ⑤는 표의자가 발신 후 도달 전 사망해도 효력에 영향이 없다는 제111조 제2항의 범위에서 도달 전 철회가 가능하다는 내용이다.","c":"중"},"변리사2016_53-09":{"w":"④가 틀리다. 무효인 계약에 기초한 외견상의 의무 위반은 채무불이행이 되지 않으므로 그 위반을 이유로 손해배상을 청구할 수 없다.\n①③은 취소 의사표시의 묵시적 방식, ②는 토지거래허가를 받기로 한 약정기간의 경과만으로 확정 무효가 되지 않는다는 판례이고, ⑤는 무효인 징계해임이 직권해임으로 전환되지 않는다는 판례이다.","c":"중"},"변리사2017_54-05":{"w":"제103조에 해당하지 않는 것은 ㄱ, ㄷ, ㄹ이다.\nㄱ 강제집행 면탈 목적의 허위 근저당권은 통정허위표시(제108조)로 무효이고 제103조 위반은 아니다.\nㄴ 과도하게 무거운 위약벌은 제103조에 반해 무효이다(해당).\nㄷ 뇌물을 소극적으로 은닉하기 위한 임치 약정은 반사회적이지 않다.\nㄹ 해외연수 후 일정 기간 근무 약정은 유효하다.\nㅁ 공무원의 직무에 관한 청탁의 대가로 금전을 지급하는 약정은 반사회적이다(해당).\n정답 ②.","c":"중"},"변리사2017_54-06":{"w":"③이 틀리다. 신원보증서류인 줄 알고 연대보증서면에 서명한 경우는 표시상 착오이고, 사기는 표시와 의사가 일치하는 경우에 적용되므로 사기를 이유로 취소할 수 없다(착오 취소만 문제).\n①은 소송행위에 민법 규정이 적용되지 않는다는 판례, ②는 타인 소유임을 알았다면 매수하지 않았을 사정이 있으면 사기 취소 가능, ④는 출장소장은 제110조 제2항의 제3자가 아니라 은행과 동일시되고, ⑤는 부당이득반환청구권과 손해배상청구권이 경합하지만 이중으로 만족을 받을 수는 없다는 내용이다.","c":"중"},"변리사2017_54-09":{"w":"③이 틀리다. 무경험은 일반적인 생활체험의 부족을 뜻하며, 특정 영역에서의 경험 부족에 한정되지 않는다(판례).\n①은 궁박·경솔·무경험 중 어느 하나만 갖추면 되고, ②는 궁박이 경제적 원인에 한정되지 않으며, ④는 폭리자의 악의가 필요하고, ⑤는 불공정한 법률행위는 추인으로 유효가 될 수 없으나 제138조 무효행위 전환은 적용될 수 있다.","c":"상"},"변리사2017_54-10":{"w":"①이 틀리다. 정지조건부 채권양도에서 정지조건이 성취되었다는 사실은 그 효력을 주장하는 쪽이 증명해야 한다.\n②는 조건의 존재를 주장하는 쪽의 증명책임, ③은 제151조 제3항(불능조건이 해제조건이면 조건 없는 법률행위), ④는 제147조가 임의규정, ⑤는 제151조 제1항(불법조건이면 법률행위 전체 무효)이다.","c":"중"},"변리사2018_55-02":{"w":"②가 옳다. 취소할 수 있는 법률행위의 상대방이 확정된 경우 취소는 그 상대방에 대한 의사표시로 한다(제142조).\n①은 무효임을 알고 추인하면 새로운 법률행위로 간주된다(제139조 단서, 추정이 아님). ③은 추인할 수 있는 날부터 3년 내에 행사하지 않으면 소멸한다(제146조). ④는 불공정한 법률행위는 추인으로 유효가 되지 않는다. ⑤는 제한능력자는 선의·악의 불문 현존이익만 반환한다(제141조 단서).","c":"상"},"변리사2018_55-05":{"w":"⑤가 틀리다. 법률행위가 반사회질서행위인지는 법률행위가 이루어진 당시(성립 시)를 기준으로 판단한다.\n①은 불법원인급여(제746조), ②는 누구든지 무효 주장 가능, ③은 강박이라는 성립 과정의 불법만으로는 제103조 위반이 아니라는 판례, ④는 본처가 부첩관계를 용서하며 손해배상청구권을 포기한 것은 유효하다는 판례이다.","c":"중"},"변리사2018_55-06":{"w":"ㄱ O. 대리인 乙이 상대방 丙을 기망하면 丙은 사기를 이유로 취소할 수 있다.\nㄴ O. 의사표시의 하자 유무는 대리인을 기준으로 정하지만(제116조 제1항), 취소권은 법률행위의 효과가 귀속되는 본인 甲에게 있다.\nㄷ O. 대리인에게 취소권을 포함한 포괄적 대리권이 수여되어 있으므로 乙도 취소할 수 있다(제140조).\n정답 ⑤.","c":"중"},"변리사2019_56-07":{"w":"③이 옳다. 착오로 인한 취소권은 추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년 안에 행사해야 한다(제146조).\n①은 동기의 착오가 상대방에 의해 제공·유발된 경우에는 취소할 수 있다. ②는 중요부분 판단에서 표의자의 경제적 불이익 여부도 고려된다. ④는 취소로 인한 부당이득반환청구권과 손해배상청구권이 경합하되 이중으로 만족을 받을 수 없다. ⑤는 제3자 사기로 인한 불법행위 손해배상은 계약을 먼저 취소하지 않아도 청구할 수 있다.","c":"중"},"변리사2023_60-07":{"w":"④가 옳다. 불공정한 법률행위(제104조)는 급부의 현저한 불균형 외에 상대방이 궁박 등을 알고 이용하려는 폭리의 악의가 있어야 성립한다.\n①은 제103조 반사회적 법률행위로 다루는 사안이다. ②는 불공정 여부를 법률행위 성립 시를 기준으로 판단하므로 이후 사정으로 생긴 불균형은 해당하지 않는다. ③은 무경험이 일반적 생활체험의 부족을 뜻한다. ⑤는 불공정성을 다투지 않기로 한 합의도 무효이다.","c":"중"},"변리사2024_61-05":{"w":"ㄱ O. 이중매매에서 배임행위에 적극 가담한 제2매수인과의 매매는 제103조 위반으로 절대적 무효이다.\nㄴ X. 제1매수인 乙은 매도인 甲을 대위하여 말소를 청구할 수 있을 뿐, 직접 丙에게 말소를 청구할 수 없다.\nㄷ X. 특정물 인도·이전등기청구권 보전을 위한 채권자취소권은 인정되지 않는다.\nㄹ X. 제103조 위반 무효는 선의의 제3자에게도 주장할 수 있어 丁은 매매계약의 유효를 주장할 수 없다.\n정답 ①.","c":"상"},"변리사2026_63-07":{"w":"ㄱ O. 복대리인은 대리인이 자기 이름으로 선임한 본인의 대리인이다.\nㄴ O. 법정대리인이 부득이한 사유로 복대리인을 선임하면 본인에 대해 선임감독 책임만 진다(제122조).\nㄷ O. 임의대리인이 복대리인을 선임하면 본인에 대해 선임감독 책임이 있다(제121조 제1항).\nㄹ O. 복임권 없는 대리인이 선임한 복대리인의 권한도 권한을 넘은 표현대리(제126조)의 기본대리권이 될 수 있다는 판례이다.\n모두 옳아 ⑤.","c":"중"},"변리사2026_63-10":{"w":"②가 해당하지 않는다. 법정추인(제145조)은 취소권자가 이행하거나 이행을 청구하는 등 취소권자 쪽의 행위이며, 취소권자에 대한 상대방의 이행 청구는 사유가 아니다.\n①은 전부나 일부의 이행, ③은 경개, ④는 담보의 제공(취소권자가 채무자로서 제공하는 경우 포함), ⑤는 취득한 권리의 전부나 일부의 양도로서 제145조 사유이다.","c":"상"},"변리사2026_63-11":{"w":"ㄱ X. 이미 성취한 조건이 해제조건이면 법률행위는 무효이다(제151조 제2항). 정지조건이면 조건 없는 법률행위가 된다.\nㄴ O. 이미 성취할 수 없는 조건이 정지조건이면 법률행위는 무효이다(제151조 제3항).\nㄷ O. 불확정한 사실의 발생 시를 이행기한으로 정한 경우, 사실이 발생한 때뿐 아니라 발생이 불가능하게 된 때에도 기한이 도래한 것으로 본다(판례).\nㄹ X. 기한이익 상실의 특약은 특별한 사정이 없는 한 형성권적 기한이익 상실 특약으로 추정된다(정지조건부가 아님).\n정답 ②.","c":"중"},"변리사2023_60-06":{"w":"옳지 않은 것은 ㄱ, ㄹ이다.\nㄱ X. 보험금청구권의 소멸시효는 보험사고가 발생한 때부터 진행하며 청구한 때부터가 아니다.\nㄴ O. 변제 충당을 지정하지 않고 일부 변제하면 특별한 사정이 없는 한 모든 채무에 대한 승인으로서 시효가 중단된다(진행 사유 부인).\nㄷ O. 중첩적 채무인수의 인수채무에는 기존채무와 같은 소멸시효기간이 적용된다.\nㄹ X. 보험금 부정 취득 목적의 다수 보험계약이 제103조로 무효가 된 경우 보험자의 부당이득반환청구권은 상행위에서 생긴 채권으로 상법 제64조의 5년 시효가 적용된다.\n정답 ②.","c":"중"},"변리사2026_63-12":{"w":"①이 중단되지 않는 경우이다. 채무자가 아닌 물상보증인이 제기한 저당권설정등기 말소 소송에 채권자가 응소해 피담보채권의 존재를 주장해도 채무자에 대한 피담보채권의 소멸시효는 중단되지 않는다(판례).\n②는 양도 대항요건을 갖추지 못한 양수인의 재판상 청구, ③은 피담보채권을 근거로 한 근저당권설정등기청구의 소, ④는 승인(제168조 제2호), ⑤는 지급명령 각하 후 6개월 내 소 제기(제170조)로 중단된다.","c":"하"},"변리사2016_53-13":{"w":"⑤가 틀리다. 친권자와 미성년자 사이의 이해상반행위에 해당하는 등기라도 등기의 추정력은 부정되지 않고, 특별대리인 선임 등 절차를 거치지 않았다는 점은 등기의 무효를 주장하는 쪽이 증명해야 한다는 취지로 풀었다.\n①은 신축자가 아닌 보존등기 명의자의 추정력이 부정되고, ②는 전 소유자에게도 추정되며, ③은 공시송달 판결에 따른 보존등기에도 추정력이 있고, ④는 대리권 없음을 주장하는 쪽이 증명한다. 판례 확인이 충분하지 않았다.","c":"하"},"변리사2017_54-17":{"w":"⑤가 틀리다. 공유물분할 조정이 성립해도 그 시점에 물권변동이 생기지 않고, 조정에 따른 지분이전등기를 마쳐야 소유권을 취득한다.\n①은 이행판결이라 등기가 필요하고, ②는 전세권 법정갱신에는 등기가 필요 없으며(제187조), ③은 건물이 완성된 이상 보존등기는 유효하고, ④는 미등기건물 양도에는 등기가 필요하다.","c":"중"},"변리사2017_54-18":{"w":"③이 틀리다. 등기원인으로 주장된 계약서가 진정하지 않다고 증명되면 등기의 추정력이 깨진다.\n①은 전 소유자에 대해서도 추정되고, ②는 허무인으로부터의 이전등기는 원인무효이며, ④는 원인 없이 말소된 등기의 명의인도 회복등기 전에 적법한 권리자로 추정되고, ⑤는 보존등기 명의자가 신축자가 아니면 추정이 깨진다.","c":"중"},"변리사2018_55-13":{"w":"⑤가 틀리다. 민사집행법상 경매의 매수인은 매각대금을 모두 낸 때 소유권을 취득하며(민사집행법 제135조), 이전등기가 된 때가 아니다.\n①은 상속(제187조), ②는 수용 개시일 취득, ③은 건축허가 명의와 무관한 원시취득이고, ④는 공유물분할 조정이 성립한 경우 지분이전등기를 마쳐야 소유권을 취득한다.","c":"상"},"변리사2018_55-18":{"w":"⑤가 옳다. 중간생략등기에 중간자 乙이 동의해도 乙의 甲에 대한 이전등기청구권은 소멸하지 않는다(판례).\n①은 특정채권이므로 乙이 무자력이 아니어도 丙이 대위행사할 수 있다. ②는 甲·乙·丙 전원의 합의가 있어야 직접 청구할 수 있다. ③은 甲·乙 간 매매가 합의해제되면 甲은 丙의 청구를 거절할 수 있다. ④는 중간생략등기가 실체관계에 부합하고 대금이 완제되었다면 합의 없다는 이유로 말소를 청구할 수 없다.","c":"중"},"변리사2023_60-16":{"w":"⑤를 정답으로 둔다. 선지는 특별조치법에 의한 보존등기가 경료된 임야에 사정받은 사람이 따로 있음이 밝혀진 경우 실체관계에 부합하는 등기로 추정되지 않는다는 내용인데, 판례상 특조법 등기는 그 사실만으로 추정이 번복되는 것은 아니라는 취지로 풀었다. 판례 확인이 되지 않았다.\n①은 중간생략등기 합의가 있어도 乙의 청구권이 소멸하지 않고, ②는 가등기상 권리 이전은 부기등기, ③은 점유하는 매수인(명의신탁자)의 이전등기청구권은 시효로 소멸하지 않으며, ④는 가등기가 있어도 소유권이전등기를 청구할 법률관계가 추정되지 않는다.","c":"하"},"변리사2024_61-13":{"w":"ㄱ O. 사인증여로 인한 소유권 취득은 법률행위에 의한 물권변동이므로 등기가 필요하다.\nㄴ O. 합유지분 포기로 지분이 다른 합유자에게 귀속되는 경우에도 등기를 해야 한다(판례).\nㄷ O. 이전등기절차 이행을 명한 판결은 이행판결이므로 등기해야 소유권을 취득한다.\nㄹ O. 점유취득시효 완성만으로 소유권을 취득하지 않고 등기를 해야 한다(제245조 제1항).\n모두 등기를 요해 ⑤.","c":"중"}};
